WITH payload AS (SELECT $archive_payload$[{"id":"e56b6eb2-5bd6-57a3-ad94-f20f282cd76f","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة بقصد الترويج والتعاطي -قات -املدعى عليه أجنبي حدث -األحداث ال تطبق بحقهم العقوبات املطبقة على غيرهم -أسباب مخففة للعقوبة -التعزير بالسجن واجللد.","document_number":"34336552","case_number":"34459998","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/11/12","year":"1434","subject":"مخدرات -حيازة بقصد الترويج والتعاطي -قات -املدعى عليه أجنبي حدث -األحداث ال تطبق بحقهم العقوبات املطبقة على غيرهم -أسباب مخففة للعقوبة -التعزير بالسجن واجللد.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 34336552 :‬تاريخه‪1434/11/12:‬هـ‬\n                   ‫رقم القضية‪34459998:‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n          ‫‪ 34368926‬تاريخه‪1434/11/25:‬هـ‬\n\n\n‫مخــدرات ‪ -‬حيــازة بقصــد الترويــج والتعاطــي ‪ -‬قــات ‪ -‬املدعــى عليــه‬\n‫أجنبــي حــدث ‪ -‬األحــداث ال تطبــق بحقهــم العقوبــات املطبقــة علــى‬\n     ‫غيرهــم ‪ -‬أســباب مخففــة للعقوبــة ‪ -‬التعزيــر بالســجن واجللــد‪.‬‬\n\n\n\n\n‫تعميــم وزيــر الداخليــة رقــم ‪ 16/13074‬يف ‪1422/2/15‬ه ـ املبنــي علــى‬\n‫مــا صــدر مــن وزارة العــدل برقــم ‪ 310‬يف ‪1394/4/7‬ه ـ القاضــي بــأن‬\n       ‫األحــداث ال يطبــق بحقهــم العقوبــات املطبقــة علــى غيرهــم ‪.‬‬\n\n\n\n\n‫ادعــى املدعــي العــام ضــد املدعــى عليــه احلـ َـدث بحيــازة قــات بقصــد‬\n‫الترويــج والتعاطــي وطلــب إثبــات مــا أســند إليــه وتعزيــره شــرع ًا‬\n‫ومصــادرة الســيارة ‪،‬حيــث مت القبــض عليــه وهــو يقود ســيارة وبتفتيشــها‬\n‫عثــر علــى نبــات القــات وأثبــت التقريــر الكيميائــي الشــرعي إيجابيــة‬\n‫العينــة املضبوطــة لنبــات القــات احملظــور ‪،‬وصــادق املدعــى عليــه علــى‬\n‫حيــازة القــات وأنهــا بقصــد االســتعمال وأنكــر الترويــج وأن الســيارة‬\n‫ليســت ملكــه ‪،‬وبنــاء علــى مــا تقــدم حكمــت احملكمــة بإثبــات‬\n‫إدانــة املدعــى عليــه بحيــازة القــات بقصــد التعاطــي بتخفيــف احلكــم‬\n‫بســجنه ســتة أشــهر نظــر ًا لكونــه حــدث واألحــداث ال تطبــق بحقهــم‬\n\n                                                                               ‫‪286‬‬\n\f      ‫العقوبــات املطبقــة علــى غيرهــم ولعــدم وجــود ســوابق عليــه وملــا ظهــر‬\n      ‫للمحكمــة مــن ظروفــه االجتماعيــة ‪،‬ولعــدم ثبــوت الترويــج وبتعزيــره‬\n      ‫لشــبهة الترويــج باجللــد ســتني جلــدة مفرقــة علــى دفعتــن وصــرف النظــر‬\n      ‫عــن طلــب املدعــي العــام مبصــادرة الســيارة وقنــع املدعــى عليــه واعتــرض‬\n      ‫‪،‬وصــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬  ‫املدعــي العــام بــدون الئحــة ُ‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪.....‬القاضــي يف احملكمــة اجلزائيــة‬\n      ‫بجــازان املكلــف حاليــا بالنظــر يف قضايــا األحــداث بخطــاب فضيلــة‬\n      ‫رئيــس احملكمــة رقــم (‪ )34190936‬يف ‪1434/8/7‬ه ـ وبنــاء علــى‬\n      ‫املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة اجلزائيــة بجــازان‬\n      ‫برقــم ‪ 34459998‬وتاريــخ ‪ 1434/10/19‬ه ـ املقيــدة باحملكمــة‬\n      ‫برقــم ‪ 342356096‬وتاريــخ ‪ 1434/10/19‬ه ـ ففــي يــوم األربعــاء‬\n      ‫املوافــق‪ 1434/10/21‬ه ـ افتتحــت اجللســة األولــى الســاعة ‪08 : 30‬‬\n      ‫وفيهــا حضــر املدعــي العــام ‪.....‬املوجــه باخلطــاب املوجــه باخلطــاب رقــم‬\n      ‫‪ 28810‬يف ‪1434/8/29‬ه ـ وادعــى علــى احلاضــر معــه احلــدث الســجني‬\n      ‫‪ ..... /‬يدعــي أن لــه معاملــة بطلــب اجلنســية الســعودية بالبطاقــة البديلــة‬\n      ‫رقــم (‪ ).....‬حيــث إنــه بتاريــخ ‪1434/8/13‬ه ـ ‪ ،‬وأثنــاء قيــام إحــدى‬\n      ‫دوريــات املجاهديــن بحراســة احلــدود واملواقــع احملــددة لهــا وأثنــاء‬\n      ‫جتولهــم يف املوقــع املســمى (‪ ).....‬أقبلــت عليهــم ســيارة مــن نــوع موديــل‬\n      ‫(‪2004‬م) حتمــل اللوحــة رقــم (‪ ).....‬تعــود ملكيتــه للمواطــن‪(..... /‬مت‬\n      ‫طلــب مصادرتهــا) وأثنــاء اقترابهــا مــن الدوريــة مت اإلشــارة لقائدهــا‬\n      ‫بالوقــوف وقــد امتثــل لذلــك ومت طلــب إثباتــه وتبــن أنــه املدعــى عليــه‬\n\n‫‪287‬‬\n\f‫‪ ،‬وبتفتيــش الســيارة عثــر بهــا علــى كميــة مــن نبــات القــات بلــغ وزنــه‬\n‫(‪75‬كجــم) خمســة وســبعني كيلــو جــرام ومت القبــض عليــه ‪.‬أثبــت‬\n‫التقريــر الكيميائــي الشــرعي رقــم ( ‪ ).....‬بتاريــخ ‪1434/8/22‬ه ـ‬\n‫الصــادر مــن مركــز الســموم والكيميــاء الشــرعية بجــازان إيجابيــة‬\n‫العينــة املرســلة مــن الكميــة املضبوطــة لنبــات القــات احملظــور املــدرج‬\n‫باجلــدول رقــم(‪ )2‬فئــة(أ‪،‬ج) واجلــدول رقــم(‪ )4‬امللحقــن بنظــام مكافحــة‬\n‫املخــدرات واملؤثــرات العقليــة الصــادر باملرســوم امللكــي رقــم م‪ 39/‬يف‬\n‫‪1426/7/8‬هــ‪ .‬وباســتجواب املدعــى عليــه أقــر بحيازتــه لكميــة القــات‬\n‫املضبوطــة مــن نبــات القــات احملظــور ذكــر بأنهــا تعــود لــه وغرضــه منها‬\n‫التعاطــي‪ ،‬وصــادق علــى أقوالــه حتقيقــا وقــد أســفر التحقيق مــع املدعى‬\n‫عليــه عــن توجيــه االتهــام إليــه بحيــازة مــا وزنــه (‪75‬كجــم) خمســة‬\n‫وســبعون كيلــو جــرام مــن نبــات القــات بقصــد الترويــج والتعاطــي‪،‬‬\n‫واملجــرم مبوجــب الفقــرة رقــم (‪ )2‬مــن املــادة (الثالثــة) مــن نظــام‬\n‫مكافحــة املخــدرات واملؤثــرات العقليــة الصــادر باملرســوم امللكــي رقــم‬\n       ‫(م‪ )39/‬وتاريــخ ‪1426/7/8‬هــ‪ .‬وذلــك لألدلــة والقرائــن التاليــة ‪:‬‬\n              ‫‪ -1‬ما جاء يف إقراره من حيازة القات للتعاطي لفه رقم(‪.)19‬‬\n‫‪ -2‬مــا ورد مبحضــر القبــض والتفتيــش املشــار لــه املرفــق بــاألوراق لفــه‬\n                                                                      ‫رقــم (‪. )2-1‬‬\n    ‫‪ -3‬ما ورد بالتقرير الكيميائي الشرعي املنوه عنه املرفق لفه (‪.)25‬‬\n                       ‫‪ -4‬كبر الكمية املضبوطة قرينة أنها معدة للترويج‬\n‫وحيــث إن مــا أقــدم عليــه احلــدث املدعــى عليــه فعــل محــرم شــرع ًا و‬\n                                            ‫معاقــب عليــه نظام ـ ًا فإنــي أطلــب‪:‬‬\n                                            ‫‪1‬ـ تعزيره شرعا لقاء ما نسب إليه ‪.‬‬\n\n\n                                                                                      ‫‪288‬‬\n\f      ‫‪-2‬مصــادرة الســيارة املســتخدمة يف اجلرميــة مــن نــوع غمارتــن موديــل‬\n      ‫(‪2004‬م) حتمل اللوحة رقم (‪ ).....‬تعود ملكيته للمواطن‪ ..... /‬مبوجب‬\n      ‫تعميــم ســمو وزيــر الداخليــة رقــم (‪ )8851‬وتاريــخ (‪1434/2/6‬هــ)‬\n      ‫‪.‬وبــاهلل التوفيــق وبعــرض مــا جــاء يف الئحــة الدعــوى علــى املدعــى عليــه‬\n      ‫صدق على صحة ما جاء فيها وأن الكمية املض ــبوطة بح ــوزته والب ــالغ‬\n      ‫وزن ــها (‪75‬كجــم) خمســة وســبعني كيلــو جــرام مــن ن ــبات ال ــقات تعــود‬\n      ‫لــه شــخصي ًا بقصــد االســتعمال هكــذا أجــاب وقــد جــرى ســؤال‬\n      ‫املدعــي العــام عــن بينتــه علــى أن الكميــة معــدة للترويــج قــال بينتــي‬\n      ‫كبــر حجــم الكميــه املضبوطــة وال يتصــور أن تكــون لالســتعمال‬\n      ‫الشــخصي وبعــرض ذلــك علــى املدعــى عليــه قــال الصحيــح مــا ذكــرت‬\n      ‫وأنهــا لالســتعمال الشــخصي وبســؤاله عــن الســيارة التــي كان يقودهــا‬\n      ‫أجــاب بأنهــا ســيارة تعــود ملكيتهــا للمدعــو ‪ ...../‬و ال علــم لــه بكميــة‬\n      ‫القــات املضبوطــة بالســيارة معــي هكــذا أجــاب وباالطــاع علــى محضر‬\n      ‫القبــض والتحقيــق وجــد مطابــق ملــا جــاء يف الئحــة الدعــوى وباالطــاع‬\n      ‫علــى التقريــر الكيميائــي الشــرعي لفــة رقــم (‪ )25‬وجــد إيجابيــة العينــة‬\n      ‫املرســلة لنبــات القــات وباإلطــاع علــى صحيفــة الســوابق لــم يعثــر له على‬\n      ‫ســوابق مســجلة حتــى حينــه فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة‬\n      ‫وحيــث اعتــرف املدعــى عليــه بحيازتــه للكميــة املرصــودة أعــاه لغــرض‬\n      ‫االســتعمال الشــخصي وحيــث أنكــر قصــد الترويــج وال بينــة للمدعــي‬\n      ‫العــام ســوى كبــر حجــم الكميــه املضبوطــة وحيــث إن مــا أقــدم عليــه‬\n      ‫فعــل محــرم ومعاقــب عليــه وحيــث إن املدعــى عليــه حــدث و األحــداث ال‬\n      ‫يطبــق بحقهــم العقوبــات املطبقــة علــى غيرهــم وذلــك وفــق لتعميــم ســمو‬\n      ‫وزيــر الداخليــة رقــم‪13074/16‬يف ‪1422/2/15‬ه ـ املبنــي علــى مــا صدر‬\n\n\n‫‪289‬‬\n\f‫مــن وزارة العــدل رقــم‪310‬يف ‪1394/4/7‬ه ـ وال ســوابق مســجلة عليــه‬\n‫وملــا ظهــر للمحكمــة مــن ظروفــه االجتماعيــة ممــا يســتدعي التخفيــف‬\n‫عليــه ومراعاتــه وملــا ســبق فقــد ثبــت لــدى إدانــة املدعــى عليــه بحيازتــه‬\n‫ملــا وزنــه (‪75‬كجــم) خمســة وســبعون كيلــو جرام ـ ًا مــن نبــات القــات‬\n‫لغــرض التعاطــي وحكمــت بتعزيــره بالســجن ملــدة ســتة أشــهر اعتبــار ًا‬\n‫مــن تاريــخ دخولــه الــدار وصرفــت النظــر عــن طلــب املدعــي العــام لعــدم‬\n‫وجــود مــا يؤيــد الترويــج ونظــر ًا لكبــر حجــم الكميــة ولوجــود شــبهة‬\n‫الترويــج فهــو يســتحق التعزيــر علــى ذلــك بجلــده ســتني جلــدة مفرقــة‬\n‫علــى فترتــن كل فتــرة ثالثــون بــن الفتــرة واألخــرى أســبوع ومبــا‬\n‫ســبق حكمــت كمــا صرفــت النظــر عــن طلــب املدعــي العــام مصــادرة‬\n‫الســيارة واالكتفــاء بعقوبــة الســجن واجللــد املقــررة بعاليــه وبهــذا انتهــت‬\n‫هــذه الدعــوى وبعــرض مــا حكمنــا بــه املدعــى عليــه قنــع بــه وقــرر‬\n‫املدعــي العــام عــدم القناعــة وطلــب رفعهــا إلــى محكمــة االســتئناف‬\n‫بــدون الئحــة اعتراضيــة وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد‬\n                       ‫وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف‪1434/10/21‬هــ‪.‬‬\n‫تابــع دعــوى املدعــي العــام ضــد احلــدث ‪.....‬يف قــات احلمــد هلل وحــده‬\n‫والصــاة والســام علــى مــن ال نبــي بعــده وبعــد ففــي هــذا اليــوم‬\n‫األربعــاء املوافــق ‪1434/11/12‬ه ـ افتتحــت اجللســة بنــاء علــى ورود‬\n‫املعاملــة املتعلقــة بهــذه الدعــوى مــن محكمــة االســتئناف مبنطقــة‬\n‫عســير برقــم (‪)342435339‬يف ‪1434/11/06‬ه ـ ومرفــق بهــا قــرار‬\n‫أصحــاب الفضيلــة قضــاة الدائــرة اجلزائيــة الثالثــة رقــم(‪)34346279‬يف‬\n‫‪1434/11/02‬ه ـ املتضمــن مالحظــة مــا يلــي أن اجلــزاء احملكــوم بــه‬\n‫علــى املدعــى عليــه قليــل الســيما مــع كبــر الكميــة مــن القــات املتهــم‬\n\n\n                                                                                     ‫‪290‬‬\n\f      ‫بترويجهــا وإقــراره بحيازتــه لهــا لقصــد االســتعمال وال بــد مــن جزاء رادع‬\n      ‫لــه فعلــى فضيلتــه مالحظــة مــا ذكــر وإكمــال الــازم‪ .‬واهلل املوفــق ‪.‬‬\n      ‫رئيــس الدائــرة الشــيخ ‪.....‬ختمــه و توقيعــه قاضــي اســتئناف الشــيخ ‪.....‬‬\n      ‫ختمــه و توقيعــه قاضــي اســتئناف الشــيخ ‪.....‬ختمــه و توقيعــه أ‪.‬هــ‪ .‬أجيــب‬\n      ‫أصحــاب الفضيلــة وفقنــي اهلل وإياهــم للصــواب بــأن املدعــى عليــه حدث‬\n      ‫وقــد أجريــت لــه عمليــة الســتئصال الغــدة الدرقيــة ويحتــاج إلــى عنايــة‬\n      ‫خاصــة وأكل مخصــوص كمــا هــو مبــن علــى لفــة رقــم (‪ )22‬وجلميــع‬\n      ‫مــا ســبق فأنــا أرى أن العقوبــة املقــررة ســابق ًا كافيــة لردعــه وزجــره‬\n      ‫وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه أجمعــن ‪.‬‬\n                                                            ‫حــرر يف ‪1434/11/12‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة الثالثــة‬\n      ‫لتدقيــق القضايــا اجلزائيــة مبحكمــة االســتئناف مبنطقــة عســير علــى‬\n      ‫املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة بجــازان برقــم‬\n      ‫‪ 342580339‬وتاريــخ ‪1434/11/12‬ه ـ املرفــق بهــا القــرار الصــادر مــن‬\n      ‫فضيل ــة القاضــي باحملكمــة الشــيخ‪..... /‬برقــم ‪ 34336552‬وتاريــخ‬\n      ‫‪1434/10/21‬ه ـ اخلــاص بدعــوى املدعــي العــام ض ـ ـ ـ ـ ــد احلــدث ‪-..... /‬‬\n      ‫يدعــي أنــه ســعودي ‪ -‬يف قضيــة ( قــات ) علــى الصفــة املوضحــة يف‬\n      ‫القــرار املتضمــن حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه وحيــث‬\n      ‫ســبق دراســة القــرار وصــورة ضبطــه وأوراق املعاملــة وباالطــاع علــى مــا‬\n      ‫ـاء علــى قرارنــا رقــم‬\n                            ‫أجــاب بــه فضيلتــه وأحلقــه بالقــرار وصــورة ضبطــه بنـ ً‬\n      ‫( ‪ ) 34346279‬وتاريــخ ‪1434/11/2‬ه ـ ‪ .‬تقــررت املوافقــة علــى احلكــم‬\n      ‫بعــد اإلجــراء األخيــر واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه‬\n                                                                        ‫وصحبــه وســلم ‪.‬‬\n\n\n‫‪291‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"c99e10bc-04e4-545e-ba4d-827d4f791349","source_page_start":286,"source_page_end":291,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"29d3782d217d2a2629098d4cf2156b80e9599cc9383d98543c185827ffe3412e","normalized_text_hash":"9ec322f0f6cabc438de6682b685165970d8ab5cf9f3966be29f068dc10ca2c67","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v21-p286-34336552"},{"id":"31a27cbc-0b1f-59ef-b1d3-35ca8ebd4bc4","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة بقصد التعاطي -قات -املرء مؤاخذ بإقراره- تداخل العقوبات التعزيرية -التعزير بالسجن واجللد.","document_number":"34340390","case_number":"34470023","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/10/26","year":"1434","subject":"مخدرات -حيازة بقصد التعاطي -قات -املرء مؤاخذ بإقراره- تداخل العقوبات التعزيرية -التعزير بالسجن واجللد.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 34340390:‬تاريخه‪1434/10/26:‬هـ‬\n                   ‫رقم الدعوى‪34470023:‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n          ‫‪ 35116759‬تاريخه‪1435/01/16:‬هـ‬\n\n\n‫مخــدرات ‪ -‬حيــازة بقصــد التعاطــي ‪ -‬قــات ‪ -‬املــرء مؤاخــذ بإقــراره‪-‬‬\n          ‫تداخــل العقوبــات التعزيريــة ‪ -‬التعزيــر بالســجن واجللــد‪.‬‬\n\n\n\n\n‫‪ -1‬مــا نــص عليــه أهــل العلــم مــن تداخل العقوبات التعزيرية (كشــاف‬\n                                                   ‫القناع‪. ) 113/14‬‬\n                         ‫‪ -2‬القاعدة الفقهية‪ :‬املرء مؤاخذ بإقراره‪.‬‬\n                  ‫‪ -3‬قرار مجلس الوزراء رقم (‪ )11‬يف ‪1374/2/1‬هـ‪.‬‬\n              ‫‪ -4‬قرار وزير الداخلية رقم (‪ )2057‬يف ‪1404/5/26‬هـ‪.‬‬\n\n\n\n\n‫ادعــى املدعــي العــام ضــد املدعــى عليــه بحيــازة قــات بقصــد التعاطــي‬\n‫وتعاطــي نوعهــا وطلــب إثبــات مــا أســند إليــه وتعزيــره بالســجن ‪،‬حيــث‬\n‫أنــه مت القبــض علــى املدعــى عليــه مــن قبــل فرقــة املكافحــة بعــد نزولــه‬\n‫مــن ســيارته وبتفتيــش الســيارة عثــر بهــا علــى كميــة مــن نبــات يشــتبه أن‬\n‫تكــون مــن نبــات القــات وأثبــت التقريــر الكيميائــي الشــرعي إيجابيــة‬\n‫العينــة املضبوطــة لنبــات القــات احملظــور وصــادق املدعــى عليــه علــى‬\n‫الدعــوى وأبــدى النــدم والتوبــة ‪،‬وبنــاء علــى مــا تقــدم حكمــت احملكمة‬\n‫بســجنه عشــرين يومـ ًا وجلــده خمســن جلــدة دفعــة واحــدة وقنــع املدعــى‬\n\n                                                                                    ‫‪292‬‬\n\f      ‫‪،‬وصــدق احلكــم مــن‬\n                       ‫عليــه باحلكــم واعتــرض املدعــي العــام بالئحــة ُ‬\n                                                    ‫محكمــة االســتئناف‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد ففــي يــوم األحــد املوافــق ‪1434/10/25‬ه ـ لــدي‬\n      ‫ـاء علــى املعاملــة احملالــة‬\n                                 ‫أنــا ‪.....‬القاضــي باحملكمــة اجلزائيــة بالدمــام وبنـ ً‬\n      ‫إلينــا مــن رئيس احملكمــة برقم (‪ )34470023‬وتاريخ ‪1434/10/22‬هـ‬\n      ‫افتتحــت اجللســة وفيهــا حضــر ‪.....‬ســعودي اجلنســية مبوجــب الســجل‬\n      ‫املدنــي رقــم (‪ ).....‬وقــدم املدعــي العــام ‪.....‬الئحــة اإلدعــاء املتضمنــة‬\n      ‫بصفتــي مدعي ـ ًا عام ـ ًا بدائــرة اإلدعــاء العــام لفــرع الهيئــة باملنطقــة‬\n      ‫الشــرقية أدعــي علــى املذكــور أعــاه أنــه وباالطــاع علــى محضــر‬\n      ‫البــاغ املعــد مــن مكافحــة املخــدرات بالدمــام بتاريــخ ‪1434/9/12‬ه ـ‬\n      ‫املتضمــن أنــه بنــاء علــى املعلومــات الــواردة مــن أحــد املصــادر الســرية عــن‬\n      ‫وجــود شــخص يدعــى ‪..... /‬يقــوم بتعاطــي وحيــازة نبــات القــات احملظــور‬\n      ‫بحــي ‪.....‬بالدمــام وباالطــاع كذلــك علــى محضــر القبــض تبــن أنــه‬\n      ‫بتمركــز الفرقــة يف املوقــع توقفــت ســيارة بيضــاء اللــون مــن نــوع حتمــل‬\n      ‫اللوحــة رقــم (‪).....‬ونــزل منهــا شــخص تنطبــق عليــه املواصفــات التــي‬\n      ‫ذكرهــا املصــدر وباالقتــراب منــه للكشــف عــن هويتــه أتضــح انــه‬\n      ‫املدعــى عليــه أعــاه وبتفتيــش ســيارته ُعثــر بهــا علــى حزمــة يشــتبه أن‬\n      ‫تكــون مــن نبــات القــات بلــغ وزنهــا (‪ )89‬تســعة وثمانــن جرامـ ًا كانــت‬\n      ‫مخبــأة حتــت عجلــة القيــادة فتــم القبــض عليــه وورد تقريــر الكيميائــي‬\n      ‫الشــرعي رقــم (‪ ).....‬وتاريخ‪1434/9/21‬ه ـ متضمن ـ ًا ثبــوت إيجابيــة‬\n      ‫حزمــة النبــات املضبوطــة لنبــات القــات احملظــورة وبســماع أقــوال‬\n\n‫‪293‬‬\n\f‫املدعــى عليــه األوليــة أقــر بحيــازة نبــات القــات املخــدر احملظــور بقصــد‬\n‫التعاطــي انتهــى التحقيــق إلــى توجيــه االتهــام للمدعــى عليــه ب ــحيازة‬\n‫حزمــة مــن نبــات القــات املخــدر بلــغ إجمالــي وزنهــا‪ 89‬تســعة وثمانــن‬\n‫جرامـ ًا بقصــد التعاطــي وتعاطــي نوعهــا وذلــك لألدلــة والقرائــن التاليــة‬\n‫‪ -1 :‬إقــراره مبحضــر ســماع األقــوال األوليــة املنــوه عنــه واملــدون علــى‬\n‫الصفحــة رقــم ‪ 21‬واملرفــق لفــة رقــم(‪ -2 )1‬مــا ورد يف محضــر البــاغ‬\n‫املنــوه عنــه مبحضــر االســتدالل واملــدون علــى الصفحــة رقــم ‪ 2‬واملرفــق‬\n‫لفــة رقــم (‪ -3 )1‬مــا ورد يف محضــر القبــض مــن وقائــع املنــوه عنهــا‬\n‫واملدونــة علــى الصفحــة رقــم ‪ 12‬واملرفقــة لفــة رقــم (‪ -4 )1‬مــا ورد يف‬\n‫التقريــر الكيميائــي الشــرعي املنــوه عنــه واملرفــق لفــة رقــم وحيــث أن‬\n‫مــا أقــدم عليــه املذكــور وهــو بكامــل أهليتــه املعتبــرة شــرعا فعــل‬\n‫محــرم ومعاقــب عليــه شــرع ًا ونظامـ ًا أطلــب احلكــم عليــه إثبــات إدانتــه‬\n‫وفقــا للقــرار رقــم ‪ 11‬يف ‪1374/2/1‬ه ـ واحلكــم عليــه‬      ‫مبــا أســند إليــه ً‬\n‫بعقوبــة الســجن والتعزيــر الــواردة يف املــادة ‪ 4‬فقــرة ‪ 1.2‬مــن القــرار‬\n‫املشــار إليــه وبــاهلل التوفيــق وبســؤال املدعــى عليــه أجــاب بقولــه مــا‬\n‫ذكــره املدعــي العــام صحيــح جملــة وتفصيــا وأنــا تائــب ونــادم وأتعهــد‬\n‫بعــدم العــودة ملثــل مــا بــدر منــي هــذه إجابتــي وبعــد تدويــن مــا ســبق جــرى‬\n‫االطــاع علــى التقريــر الكيمــاوي الشــرعي رقــم (‪ ).....‬املتضمــن ثبــوت‬\n‫أن عينــة املضبــوط يف هــذه القضيــة لنبــات القــات احملظــور كمــا جــرى‬\n‫االطــاع علــى صحيفــة الســوابق املرفقــة باملعاملــة واملتضمنــة عــدم وجود‬\n‫ســوابق مســجلة علــى املدعــى عليــه فبنــاء علــى مــا تقــدم مــن الدعــوى‬\n‫واإلجابــة املتضمنــة املصادقــة عليهــا وحيــث إن املــرء مؤاخــذ بإقــراره‬\n‫وبنــاء علــى التقريــر الكيمــاوي الشــرعي املشــار إليــه أعــاه واســتناد ًا‬\n\n\n                                                                                         ‫‪294‬‬\n\f      ‫لقــرار مجلــس الــوزراء رقــم (‪ )11‬وتاريــخ ‪1374/2/1‬ه ـ واســتنادا للقرار‬\n      ‫الــوزاري رقــم(‪ )2057‬وتاريــخ ‪1404/5/26‬ه ـ املتضمــن أن عقوبــات‬\n      ‫الســجن والغرامــة الــواردة يف قــرار مجلــس الــوزراء رقم(‪)11‬هــي احلــد‬\n      ‫األعلــى ملــا ميكــن للجهــة املختصــة احلكــم بــه علــى املتهــم عنــد ثبــوت‬\n      ‫إدانتــه وحيــث إن العقوبــة علــى تعاطــي القــات تعزيريــة وبنــاء علــى مــا‬\n      ‫نــص عليــه أهــل العلــم مــن تداخــل العقوبــات التعزيريــة (كشــاف القنــاع‬\n      ‫‪ )113/14‬وحيــث أظهــر املدعــى عليــه التوبــة والندم ولعدم وجود ســوابق‬\n      ‫مســجلة عليــه لــذا فقــد ثبــت لــدي إدانــة املدعــى عليــه بحيــازة حزمــة مــن‬\n      ‫نبــات القــات املخــدر بلــغ إجمالــي وزنهــا تســعة وثمانــون جرامــا بقصــد‬\n      ‫التعاطــي وتعاطــي نوعهــا وحكمــت عليــه لقــاء ذلــك بســجنه عشــرين‬\n      ‫يومــا حتتســب منــه املــدة التــي مت إيقافــه فيهــا علــى ذمــة هــذه القضيــة‬\n      ‫وجلــده خمســن جلــدة دفعــة واحــدة وبعــرض احلكــم علــى املدعــى عليــه‬\n      ‫قــرر القناعــة بــه وقــرر املدعــي العــام االعتــراض بالئحــة فأجيــب لطلبــه‬\n      ‫ومت تســليمه نســخة مــن احلكــم وأفهــم بتقــدمي االعتــراض عليــه خــال‬\n      ‫مهلــة ثالثــن يومــا وأنــه إذا انتهــت هــذه املهلــة ولــم يتقــدم باعتراضــه‬\n      ‫ســقط حقــه يف ذلــك وســوف يتــم رفــع احلكــم إلــى محكمــة االســتئناف‬\n      ‫بــدون الئحــة اعتراضيــة وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد‬\n                                                       ‫وبــه حــرر يف ‪1434/10/25‬هــ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة اجلـزائي ــة‬\n      ‫األولــى مبحكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة‬\n      ‫الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة مبدينــة الدمــام برقــم‬\n      ‫‪ 342400252‬وتاريــخ ‪1434/11/27‬ه ـ املقيــدة لــدى احملكمــة برقــم‬\n      ‫‪ 342833712‬وتاريــخ ‪1434/12/22‬ه ـ املرفــق بهــا القــرار الصــادر‬\n\n\n‫‪295‬‬\n\f‫مــن فضيلــة القاضــي باحملكمــة الشيخ‪.....‬املســجل برقــم ‪34340390‬‬\n‫وتاريــخ ‪1434/10/26‬ه ـ اخلــاص بدعوى‪/‬املدعــي العــام ضــد‪...../‬يف‬\n‫قضيــة قــات وقــد تضمــن القــرار حكــم فضيلتــه مبــا هــو مــدون ومفصــل‬\n‫فيــه ‪ .‬وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة قررنــا املصادقــة‬\n‫علــى احلكــم واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه‬\n                                           ‫وســلم حــرر يف ‪1435/1/15‬ه ـ‬\n\n\n\n\n                                                                                 ‫‪296‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"c99e10bc-04e4-545e-ba4d-827d4f791349","source_page_start":292,"source_page_end":296,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"2e4f2cfb5243ef9a4e3800a9f8780f8dc4d9556d0fe8b649f6b8ad10ceeb767a","normalized_text_hash":"596b88e39ca816d4bca3f219119dc8f17ee9b3136da4886c3939a9be8b20ca17","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v21-p292-34340390"},{"id":"d4bbcfb5-05dd-5df9-baf4-f7234c9f1e0b","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة بقصد التعاطي -قات -أسباب مخففة للعقوبة - التعزير بالسجن واجللد واإلبعاد عن الباد .","document_number":"34363544","case_number":"34507098","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/11/19","year":"1434","subject":"مخدرات -حيازة بقصد التعاطي -قات -أسباب مخففة للعقوبة - التعزير بالسجن واجللد واإلبعاد عن الباد .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 34363544:‬تاريخه ‪1434/11/19‬هـ‬\n                         ‫رقم الدعوى‪34507098:‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 35110817‬تاريخه‪1435/1/09:‬هـ‬\n\n\n      ‫مخــدرات ‪ -‬حيــازة بقصــد التعاطــي‪ -‬قــات ‪ -‬أســباب مخففــة للعقوبــة ‪-‬‬\n                            ‫التعزيــر بالســجن واجللــد واإلبعــاد عــن البــاد ‪.‬‬\n\n\n\n\n        ‫‪ -1‬قوله صلى اهلل عليه وسلم ( كل مسكر خمر وكل خمر حرام) ‪.‬‬\n                                  ‫‪ -2‬القرار الوزاري رقم (‪ )11‬يف ‪1374/2/1‬هـ ‪.‬‬\n                    ‫‪ -3‬األمر السامي الكرمي رقم (‪ )59633‬يف ‪ 1432/12/9‬هـ ‪.‬‬\n      ‫‪ -4‬املادة الرابعة من قرار وزير الداخلية رقم (‪ )2057‬يف ‪1404/5/26‬هـ‪.‬‬\n      ‫‪ -5‬الفقــرة (ج) مــن املــادة اخلامســة مــن قــرار وزيــر الداخليــة رقــم‬\n                                                  ‫(‪ )2057‬يف ‪ 1404/5/26‬هــ‪.‬‬\n         ‫‪ -6‬الفقرة (د) من قرار وزير الداخلية رقم (‪ )2057‬يف ‪1404/5/26‬هـ‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــى العــام ضــد املدعــى عليــه بحيــازة قــات بقصــد التعاطــي و‬\n      ‫طلــب إثبــات مــا أســند إليــه ومعاقبتــه تعزيــر ًا وإبعــاده عــن البــاد ‪،‬حيــث‬\n      ‫مت القبــض علــى املدعــى عليــه أثناء قيام الدوريــة األمنية بعملها وبحوزته‬\n      ‫نبــات أخضــر يشــتبه أن يكــون قــات وأثبــت التقريــر الكيميائــي‬\n      ‫الشــرعي إيجابيــة العينــة لنبــات القــات احملظــور ‪،‬ومت إثبــات حيازتــه‬\n      ‫للقــات بقصــد التعاطــي ‪،‬وصــادق املدعــى عليــه باالدعــاء املوجــه إليــه‬\n\n‫‪297‬‬\n\f‫وأظهــر النــدم والتوبــة ‪،‬وبنــاء علــى مــا تقــدم حكمــت احملكمــة بســجنه‬\n‫ثالثــة أشــهر وجلــده خمســن جلــده دفعــة واحــدة وإبعــاده عــن البــاد بعــد‬\n‫انتهــاء محكوميتــه وقنــع املدعــى عليــه واعتــرض املدعــي العــام بــدون‬\n                        ‫‪،‬وصــدق احلكــم مــن محكمــة االســتئناف‪.‬‬ ‫الئحــة ُ‬\n\n\n\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد فلــدي‬\n‫أنــا ‪.....‬لقاضــي يف احملكمــة اجلزائيــة بجــازان وبنــاء علــى املعاملة احملالة‬\n‫لنــا مــن فضيلــة رئيــس احملكمــة اجلزائيــة بجــازان برقــم ‪34507098‬‬\n‫وتاريــخ ‪1434/11/11‬ه ـ املقيــدة باحملكمة برقــم ‪ 342571049‬وتاريخ‬\n‫‪1434/11/11‬ه ـ ففــي يــوم األربعــاء املوافــق ‪1434/11/19‬ه ـ افتتحــت‬\n‫اجللســة األولــى الســاعة العاشــرة والنصــف صباحـ ًا وفيهــا حضــر املدعــي‬\n‫العام ‪.....‬املعمد بالعمل مبوجب خطاب رقم ‪.....‬وتاريخ ‪1434/08/29‬هـ‬\n‫وحضــر املدعــى عليــه ‪..... /‬ي ــمني اجلنســية مبوجــب البطاقــة البديلــة رقــم‬\n‫(‪ ).....‬وتاريــخ ‪1434/09/21‬ه ـ بصفتــي مدعي ـ ًا عام ـ ًا بدائــرة اإلدعــاء‬\n‫العــام لفــرع الهيئــة مبنطقــة جــازان أدعــي علــى املذكــور أعــاه أنــه يف‬\n‫متــام الســاعة الثامنــة مــن مســاء يــوم االثنــن املوافــق ‪1434/9/21‬هــ‪،‬‬\n‫وأثنــاء قيــام إحــدى دوريــات شــرطة العارضــة بعملهــا املعتــاد يف محافظــة‬\n‫العارضــة مت القبــض علــى املدعــى عليــه املذكــور وبحوزتــه كميــة مــن‬\n‫نبــات أخضــر يشــتبه أن تكــون مــن نبــات القــات احملظــور بلــغ وزنهــا‬\n‫(‪ 3,250‬كجــم) ثالثــة كيلــو ومائتــن وخمســن جرام ـ ًا ‪ ،‬وأثبــت‬\n‫التقريــر الكيميائــي الشــرعي رقــم (‪ ).....‬بتاريــخ ‪1434/10/3‬ه ـ‬\n‫الصــادر مــن مركــز مراقبــة الســموم والكيميــاء الطبيــة الشــرعية‬\n\n                                                                                     ‫‪298‬‬\n\f      ‫بجــازان إيجابيــة العينــة املرســلة مــن الكميــة املضبوطــة لنبــات القــات‬\n      ‫احملظــور املــدرج باجلــدول رقــم (‪ )2‬فئــة (أ‪،‬ج) واجلــدول رقــم (‪ )4‬امللحقــن‬\n      ‫بنظــام مكافحــة املخــدرات واملؤثــرات العقليــة الصــادر باملرســوم‬\n      ‫امللكــي رقــم م‪ 39/‬يف ‪1426/7/8‬ه ـ ‪ ،‬ومت إيقافــه اســتناد ًا لنــص‬\n      ‫املــادة رقــم (‪ )108‬مــن نظــام اإلجــراءات اجلزائيــة باســتجواب املدعــى‬\n      ‫عليــه ومواجهتــه بالتهمــة املنســوبة إليــه أقــر بحيازتــه لكميــة القــات‬\n      ‫املضبوطــة البالــغ وزنهــا (‪ 3,250‬كجــم) ثالثــة كيلــو ومائتني وخمســن‬\n      ‫جرام ـ ًا مــن نبــات القــات احملظــور ذكــر بأنهــا تعــود لــه وغرضــه منهــا‬\n      ‫التعاطــي‪ ،‬ومت االكتفــاء مبحضــر ســماع األقــوال بعــد إقــراره بصحتهــا‬\n      ‫ومصادقتــه عليهــا وقــد أســفر التحقيــق عــن توجيــه االتهــام إلــى املدعــى‬\n      ‫عليــه بحيــازة مــا وزنــه (‪ 3,250‬كجــم) ثالثــة كيلــو ومائتــن وخمســن‬\n      ‫جرام ـ ًا مــن نبــات القــات احملظــور بقصــد التعاطــي واملجــرم مبوجــب‬\n      ‫القــرار الــوزاري رقــم (‪ )11‬لعــام ‪1374‬ه ـ املــادة (الرابعــة) إنفــاذ ًا لألمــر‬\n      ‫الســامي الكــرمي رقــم (‪ )59633‬وتاريــخ ‪1432/12/9‬ه ـ وذلــك لألدلــة‬\n      ‫والقرائــن التاليــة ‪ -1 :‬مــا جــاء يف إقــراره مبحضــر االكتفــاء باألقــوال‬\n      ‫واإلجــراءات األوليــة لفــه رقــم (‪ -2 )16‬مــا ورد مبحضــر القبــض‬\n      ‫والتفتيــش املشــار لــه املرفــق بــاألوراق لفــه رقــم (‪ -3 )1‬مــا ورد بالتقريــر‬\n      ‫الكيميائــي الشــرعي املنــوه عنــه املرفــق لفــه (‪ )20‬حيــث إن مــا أقــدم‬\n      ‫عليــه املذكــور فعــل محــرم شــرع ًا و معاقــب عليــه نظامـ ًا مبوجــب قــرار‬\n      ‫مجلــس الــوزراء رقــم (‪ )11‬لعــام ‪1374‬ه ـ ومــا حلــق بــه مــن تعديــات لــذا‬\n      ‫أطلــب ‪ :‬إثبــات إدانتــه مبــا أســند إليــه واحلكــم بتعزيــره يف ضــوء املــادة‬\n      ‫(الرابعــة) مــن القــرار الــوزاري املشــار إليــه أعــاه إنفــاذ ًا لألمــر الســامي‬\n      ‫الكــرمي رقــم (‪ )59633‬وتاريــخ ‪1432/12/9‬ه ـ وإبعــاده عــن البــاد‬\n\n\n‫‪299‬‬\n\f‫اســتناد ًا لتعميــم وزيــر الداخليــة رقــم (‪ )69935‬يف ‪1433/6/18‬ه ـ هــذه‬\n‫دعــواي ‪ ،‬وقــد حضــر املدعــى عليــه وبعــد التأكــد مــن هويتــه وأهليتــه‬\n‫جــرى ســؤاله عــن الدعــوى فأجــاب قائــا إن مــا ذكــره املدعــي العــام‬\n‫مــن اتهامــي بحيازتــي مــا وزنــه (‪3.250‬كجــم ) ثالثــة كيلــو ومائتــن‬\n‫وخمســن جرام ـ ًا مــن القــات احملظــور بقصــد االســتعمال والتعاطــي‬\n‫فهــذا كلــه صحيــح هكــذا أجــاب فجــرى االطــاع علــى كامــل أوراق‬\n‫املعاملــة ومنهــا محضــر القبــض املرفــق باملعاملــة فوجدتــه يتضمــن‬\n‫القبــض علــى املدعــى عليــه وبحوزتــه الكميــة املذكــورة يف الدعــوى‬\n‫كمــا جــرى االطــاع علــى كــرت ســوابق املدعــى عليــه فلــم يعثــر لــه‬\n‫علــى ســوابق مســجله كمــا جــرى االطــاع علــى التقريــر الكيمــاوي‬\n‫الشــرعي املرفــق باملعاملــة الصــادر مــن مديــر مركــز مراقبــة الســموم‬\n‫والكيمياء الطبية الشــرعية بجازان برقم (‪ ).....‬وتاريخ ‪1434/10/03‬‬\n‫ه ـ فوجدتــه يتضمــن ايجابيــة العينــة للقــات احملظــورة فبنــاء علــى مــا‬\n‫تقــدم مــن الدعــوى واإلجابــة وحيــث اعتــرف املدعــى عليــه بحيــازة‬\n‫الكميــة املذكــورة يف الدعــوى بقصــد االســتعمال والتعاطــي وحيــث ال‬\n‫توجــد ســوابق مســجلة عليــه وحيــث أثبــت التقريــر الكيمــاوي الشــرعي‬\n‫ايجابيــة العينــة للقــات احملظــور ومبــا أن مــا أقــدم عليــه املدعــى عليــه‬\n‫مــن احملــرم شــرعا ملــا يف اســتعمال القــات مــن أضــرار بليغــة علــى الديــن‬\n‫و النفــس والعقــل والعــرض واملــال ولقولــه صلــى اهلل عليــه وســلم ‪( :‬‬\n‫كل مســكر خمــر وكل خمــر حــرام ) ممــا يســتوجب إيقــاع العقوبــة‬\n‫‪ ،‬ومبــا أن املدعــى عليــه قــد اعتــرف وظهــرت عليــه آثــار التوبــة والنــدم‬\n‫فيتوجــه التخفيــف عــن العقوبــة الــواردة باحلــد األدنــى اســتنادا للفقــرة‬\n‫(ج) مــن املــادة اخلامســة مــن القــرار الــوزاري رقــم (‪ )2057‬وتاريــخ‬\n\n\n                                                                                     ‫‪300‬‬\n\f      ‫‪1404/05/26‬ه ـ لــذا كلــه وألجــل احلــق العــام حكمــت علــى املدعــى‬\n      ‫عليــه مبــا يلــي أوال ‪ :‬ثبــت لــدي إدانــة املدعــى عليــه بحيــازة مــا وزنــه‬\n      ‫‪3,250‬كجــم ثالثــة كيلــو ومائتــن وخمســون جرام ـ ًا للقــات احملظــور‬\n      ‫لقصــد االســتعمال والتعاطــي ثانيــا ‪ :‬حكمــت بســجنه ملــدة ثالثــة أشــهر‬\n      ‫حتتســب منهــا مــدة إيقافــه علــى ذمــة القضيــة وذلــك اســتنادا علــى القرار‬\n      ‫الــوزاري رقــم (‪ )11‬وتاريــخ ‪ 1374/2/1‬ه ـ واملــادة الرابعــة من قرار ســمو‬\n      ‫وزيــر الداخليــة رقــم (‪ )2057‬وتاريــخ ‪1404/05/26‬ه ـ وتطبيقــا لألمــر‬\n      ‫الســامي رقــم (‪ )59633‬وتاريــخ ‪ 1432/12/09‬ه ـ وتطبيقــا للمــادة‬\n      ‫اخلامســة فقــرة (ج) مــن ذات القــرار ثانيـ ًا حكمــت بجلــده خمســن جلــده‬\n      ‫دفعــة واحــدة وذلــك الســتعماله للقــات احملظــور ثالث ـ ًا كمــا حكمــت‬\n      ‫بإبعــاده عــن اململكــة بعــد االنتهــاء مــن محكوميتــه اســتنادا للمــادة‬\n      ‫األولــى يف الفقــرة ( د ) مــن قــرار وزيــر الداخليــة رقــم (‪ ) 2057‬وتاريــخ‬\n      ‫‪1404/05/26‬ه ـ وبعــرض احلكــم عليــه قــرر قناعتــه بــه كمــا قــرر‬\n      ‫املدعــي العــام عــدم القناعــة وطلــب االســتئناف بــدون الئحــة مكتفيــا‬\n      ‫مبــا قدمــه مــن أوراق عليــه فســيتم رفــع كامــل أوراق املعاملــة حملكمــة‬\n      ‫االســتئناف لتدقيــق احلكــم واختتمــت اجللســة الســاعة احلاديــة عشــرة‬\n      ‫وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‬\n      ‫حــرر بتاريــخ ‪ 1434/11/19‬ه ـ ‪.‬احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحن‬\n      ‫قضــاة الدائــرة األولــى لتدقيــق القضايــا اجلزائيــة مبحكمــة االســتئناف‬\n      ‫مبنطقــة عســير علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة‬\n      ‫اجلزائيــة بجــازان برقــم ‪ 342571049‬وتاريــخ ‪1434/12/2‬ه ـ املرفــق‬\n      ‫بهــا القــرار الصــادر مــن فضيلــة القاضــي باحملكمــة الشــيخ‪..... /‬برقــم‬\n      ‫‪ 34363544‬وتاريــخ ‪1434/11/19‬ه ـ اخلــاص بدعــوى املدعــي العــام‬\n\n\n‫‪301‬‬\n\f‫ضــد ‪(..... /‬مينــي اجلنســية) يف قضيــة (قــات) علــى الصفــة املوضحــة يف‬\n‫القــرار املتضمــن حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه وبدراســة‬\n‫القــرار وصــورة ضبطــه وأوراق املعاملــة تقــررت املوافقــة علــى احلكــم ‪.‬‬\n      ‫واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                ‫‪302‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"c99e10bc-04e4-545e-ba4d-827d4f791349","source_page_start":297,"source_page_end":302,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"124e1fac3fafb3308d828fe4262b51f2b7660f35e82ca49a2b5576d73c54027d","normalized_text_hash":"f9a8ad0b68a6645c74f430b26671772de649aa62d03809956cd18c35e42259a8","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v21-p297-34363544"},{"id":"5e65a417-714c-555d-8b61-9dd4721e3063","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة احلبوب احملظورة بقصد التعاطي -إقرار -التعزير بالسجن واجللد واملنع من السفر.","document_number":"34369814","case_number":"34523570","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة حفر الباطن","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/11/25","year":"1434","subject":"مخدرات -حيازة احلبوب احملظورة بقصد التعاطي -إقرار -التعزير بالسجن واجللد واملنع من السفر.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك ‪ 34369814:‬تاريخه‪1434/11/25 :‬هـ‬\n                          ‫رقم الدعوى‪34523570:‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 35116223‬تاريخه‪1435/01/15:‬هـ‬\n\n\n       ‫مخــدرات‪ -‬حيــازة احلبــوب احملظــورة بقصــد التعاطــي ‪ -‬إقرار ‪ -‬التعزير‬\n                                          ‫بالســجن واجللــد واملنع من الســفر‪.‬‬\n\n\n\n\n       ‫الفقــرة األولــى مــن املادتــن احلاديــة واألربعــن والسادســة واخلمســن‪،‬‬\n            ‫واملــادة الســتون مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة‪.‬‬\n\n\n\n\n       ‫ادعــى املدعــي العــام ضــد املدعــى عليــه بتهريــب ثــاث حبــات مــن‬\n       ‫اإلمفيتامــن احملظــورة بقصــد التعاطــي وتعاطيــه لهــا وذلــك بعــد القبــض‬\n       ‫عليــه يف أحــد املنافــذ اجلمركيــة وبقيادتــه حافلــة بتفتيشــها مت العثــور‬\n       ‫علــى احلبــوب املذكــورة‪ -‬أثبــت التقريــر الكيميائــي الشــرعي ايجابيــة‬\n       ‫احلبــوب ملــادة االمفيتامــن احملظــور ‪ -‬بالبحــث عــن ســوابقه لــم يعثــر لــه‬\n       ‫علــى ســوابق جنائيــة‪ ،‬وطلــب املدعــي العــام احلكــم عليــه بتعزيــره وفقـ ًا‬\n       ‫للعقوبــة الــواردة يف الفقــرة رقــم (‪)1‬مــن املادة رقم (‪ )41‬ومنعه من الســفر‬\n       ‫بعــد انتهــاء محكوميتــه وفقــا للفقــرة رقــم (‪)1‬مــن املــادة رقــم (‪)56‬مــن‬\n       ‫نظــام مكافحــة املخــدرات واملؤثــرات‪ -‬بعــرض ذلــك علــى املدعــى عليــه‬\n       ‫صــادق علــى حيــازة احلبــوب املذكــورة بقصــد التعاطــي وأقــر بالتعاطــي‬\n       ‫وقــرر توبتــه‪ ،‬بنــاء علــى مــا تقــدم حكمــت احملكمــة علــى املدعــى عليــه‬\n\n‫‪303‬‬\n\f‫بالســجن مــدة شــهرين وجلــده خمســن جلــدة دفعــة واحــده ومنعــه مــن‬\n‫الســفر خــارج اململكــة بعــد خروجــه مــن الســجن مــدة ســنتني وبعــرض‬\n‫احلكــم علــى املدعــي العــام واملدعــى عليــه قــرر املدعــي العــام اعتراضــه‬\n‫علــى احلكــم مكتفيــا مبــا جــاء يف املعاملــة وقــرر املدعــى عليــه قناعتــه‬\n            ‫وبعــد رفــع احلكــم حملكمــة االســتئناف متــت املصادقــة عليــه‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪.....‬القاضــي يف احملكمــة العامــة‬\n‫مبحافظــة حفــر الباطــن وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة‬\n‫رئيــس احملكمــة العامــة بحفــر الباطــن برقــم ‪ 34523570‬وتاريــخ‬\n‫‪ 1434/11/23‬ه ـ املقيــدة باحملكمــة برقــم ‪ 342652942‬وتاريــخ‬\n‫‪ 1434/11/23‬ه ـ ففــي يــوم األحــد املوافــق‪ 1434/11/23‬ه ـ افتتحــت‬\n‫اجللســة الســاعة ‪09 : 00‬صباحاوفيهــا حضــر املدعــي العــام بدائــرة‬\n‫التحقيــق واالدعــاء العــام بحفــر الباطــن ‪.....‬وادعــى علــى احلاضــر معــه‬\n‫‪ .....‬ســعودي بالســجل املدنــي رقــم ‪.....‬قائــا يف دعــواه[ إنــه بتاريــخ‬\n‫‪1434/5/7‬ه ـ قبــض علــى املتهــم املذكــور مــن قبــل املفتــش اجلمركــي‬\n‫مبنفــذ ‪.....‬أثنــاء قدومــه مــن دولــة الكويــت وبقيادتــه بــاص مــن نــوع ‪....‬‬\n‫يحمــل اللوحــة رقم(‪).....‬إماراتيــة املصــدر وبتفتيــش البــاص باســتخدام‬\n‫الوســائل احليــة (الــكالب البوليســية)مت العثــور بــدورة ميــاه البــاص علــى‬\n‫عــدد (‪)3‬ثــاث حبــات يشــتبه أن تكــون مــن احلبــوب احملظــورة مخفيــة‬\n‫أســفل املغســلة لــم يصــرح بهــا وقــد أثبــت التقريــر الكيميائــي الشــرعي‬\n‫رقــم (‪).....‬لعــام ‪1434‬ه ـ ايجابيــة احلبــوب املظبوطــة ملــادة االمفيتامــن‬\n‫املنبــه احملظــور وباســتجوابه أقــر بحيــازة ماضبــط بحوزتــه بقصــد‬\n\n                                                                                     ‫‪304‬‬\n\f      ‫التعاطــي وانــه يتعاطــى احلبــوب احملظــورة منــذ فتــرة ليســت طويلــه‬\n      ‫وبالبحث عن ســوابقه لم يعثر له على ســوابق جنائية مســجله وملا أشــير‬\n      ‫إليــه أقــرر توجيــه االتهــام ل‪.....‬بتهريــب عــدد ثــاث حبــات مــن حبــوب‬\n      ‫االمفيتامــن املنبهــة واحملظــورة بقصــد التعاطــي وتعاطيــه لهــا واملجــرم‬\n      ‫وفــق الفقــرة (‪)2‬مــن املــادة (‪ )3‬مــن نظــام مكافحــة املخــدرات وذلــك‬\n      ‫لألدلــة والقرائــن التاليــة ‪-1‬إقــراره حتقيقــا واملــدون علــى الصفحــة رقــم‬\n      ‫(‪)1‬مــن ملــف التحقيــق املرفــق لفــة (‪ -2)13‬محضــر القبــض املعــد مــن‬\n      ‫قبــل اجلهــة القابضــة املــدون علــى اللفــة رقــم (‪ -3)5‬التقريــر الكيميائــي‬\n      ‫الشــرعي املرفــق لفــة رقــم (‪)17‬وحيــث أن مــا أقــدم عليــه املذكــور‬\n      ‫وهــو بكامــل اهليتــه املعتبــرة شــرعا فعــل محــرم ومعاقــب عليــه نظامــا‬\n      ‫ممــا يتعــن معــه احالتــه إلــى احملكمــة اجلزئيــة إلثبــات مــا اســند إليــه‬\n      ‫واحلكــم عليــه مبــا يلــي ‪-1‬بالعقوبــة الــواردة يف الفقــرة رقــم (‪)1‬مــن‬\n      ‫املــادة رقــم (‪)41‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة ‪-2‬‬\n      ‫باملنــع مــن الســفر خــارج اململكــة بعــد انتهــاء محكوميتــه وفقــا للفقــرة‬\n      ‫رقــم (‪)1‬مــن املــادة رقــم (‪)56‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n      ‫العقليــة وبــاهلل التوفيق]وبعــرض ذلــك علــى املدعــى عليــه قــال إن جميــع‬\n      ‫مــا ذكــره املدعــي العــام صحيــح فقــد قبــض علــي وبحيازتــي ثــاث‬\n      ‫حبــات مــن احلبــوب احملظــورة بقصــد التعاطــي وقــد تعاطيــت احلبــوب‬\n      ‫احملظــورة يف الســابق وأنــا تائــب إلــى اهلل تعالــى هكــذا اجــاب ثــم جــرى‬\n      ‫االطــاع علــى التقريــر الكيميائــي الشــرعي املرفــق واملتضمــن ايجابيــة‬\n      ‫احلبــوب املضبوطــة ملــادة االمفيتامــن فبنــاء علــى مــا تقــدم مــن الدعــوى‬\n      ‫واالجابــة وحيــث صــادق املدعــى عليــه علــى حيازتــه لثــاث حبــات مــن‬\n      ‫احلبــوب احملظــورة بقصــد التعاطــي وتعاطيــه لهــا وبنــاء علــى مــا جــاء يف‬\n\n\n‫‪305‬‬\n\f‫التقريــر الكيميائــي الشــرعي املثبــت ايجابيــة احلبــوب املضبوطــة ملــادة‬\n‫االمفيتامــن فلمــا ســبق كلــه فقــد ثبــت لــدي ادانــة املدعــى عليــه بحيــازة‬\n‫ثــاث حبــات مــن احلبــوب احملظــورة بقصــد التعاطــي وتعاطيــه لهــا‬\n‫كمــا ثبــت لــدي انطبــاق الفقــرة االولــى مــن املادتــن احلاديــة واالربعــن‬\n‫والسادســة واخلمســن مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة‬\n‫ونظــرا حلرمــة مــا أقــدم عليــه املدعــى عليــه ولثبــوت ادانتــه مبــا أســند‬\n‫إليــه إال أن الكميــة املضبوطــة بحوزتــه قليلــة ولعــدم وجــود ســوابق‬\n‫جنائيــة مســجلة علــى املدعــى عليــه وإعمــاال للمــادة الســتني مــن نظــام‬\n‫مكافحــة املخــدرات فقــد حكمــت علــى املدعــى عليــه مبــا يلــي اوال‬\n‫ســجن املدعــى عليــه مــدة شــهرين ثانيــا جلــد املدعــى عليــه خمســن‬\n‫جلــدة دفعــة واحــده ثالثــا منــع املدعــى عليــه مــن الســفر خــارج اململكــة‬\n‫بعــد خروجــه مــن الســجن مــدة ســنتني وبتالوتــه علــى املدعــي العــام‬\n‫واملدعــى عليــه قــرر املدعــي العــام اعتراضــه علــى احلكــم مكتفيــا مبــا‬\n‫جــاء يف املعاملــة امــا املدعــى عليــه فقــد قــرر قناعتــه باحلكــم واغلقــت‬\n‫اجللســة يف متــام الســاعة العاشــرة وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى‬\n‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/11/23‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة اجلـزائي ــة‬\n‫األولــى مبحكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة الــواردة‬\n‫مــن فضيلــة رئيــس احملكمــة العامــة مبحافظــة حفــر الباطــن برقــم‬\n‫‪ 342595068‬وتاريــخ ‪1434/11/27‬ه ـ املقيــدة لــدى احملكمــة برقــم‬\n‫‪ 342823295‬وتاريــخ ‪1434/12/19‬ه ـ املرفــق بهــا القــرار الصــادر‬\n‫مــن فضيلــة القاضــي باحملكمــة الشــيخ ‪.....‬املســجل برقــم ‪34369814‬‬\n‫وتاريــخ ‪1434/11/25‬ه ـ اخلــاص بدعوى‪/‬املدعــي العــام ضــد‪...../‬يف‬\n\n\n                                                                                         ‫‪306‬‬\n\f      ‫قضيــة مخــدرات وقــد تضمــن القــرار حكــم فضيلتــه مبــا هــو مــدون‬\n      ‫ومفصــل فيــه ‪ .‬وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة قررنــا‬\n      ‫املصادقــة علــى احلكــم واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه‬\n                                          ‫وصحبــه وســلم حــرر يف ‪1435/1/14‬ه ـ‬\n\n\n\n\n‫‪307‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"c99e10bc-04e4-545e-ba4d-827d4f791349","source_page_start":303,"source_page_end":307,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"5aeb872cfed3af09d7a2ab80565da575c9c5c93af4629306e4649e771503a65e","normalized_text_hash":"e90864ec259efffce5d14043c15761d6faea36160baf84d094cb5fd769c4135f","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v21-p303-34369814"},{"id":"a433cb01-f640-55f2-878f-a1ac75ed85e2","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة ونقل احلبوب احملظورة بقصد احلصول على املال -األسباب املوجبة لتشديد العقوبة -ثبوت -سجن -جلد -غرامة","document_number":"34390103","case_number":"34535671","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/12/26","year":"1434","subject":"مخدرات -حيازة ونقل احلبوب احملظورة بقصد احلصول على املال -األسباب املوجبة لتشديد العقوبة -ثبوت -سجن -جلد -غرامة","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك ‪ 34390103:‬تاريخه‪1434/12/26 :‬هـ‬\n                    ‫رقم الدعوى‪34535671:‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 35113824‬تاريخه‪1435/1/14 :‬هـ‬\n\n\n ‫مخــدرات ‪ -‬حيــازة ونقــل احلبــوب احملظــورة بقصــد احلصــول علــى املــال‬\n ‫‪ -‬األســباب املوجبــة لتشــديد العقوبــة ‪ -‬ثبــوت ‪ -‬ســجن ‪ -‬جلــد ‪ -‬غرامــة‬\n                                                                 ‫‪ -‬مصــادرة ‪.‬‬\n\n\n\n\n ‫املــواد (‪ )38‬و(‪ )41‬و(‪ )53‬و(‪ )56‬و(‪ )62‬مــن نظــام مكافحــة املخــدرات‬\n                                                 ‫واملؤثــرات العقليــة‪.‬‬\n\n\n\n ‫اتهــام املدعــي العــام للمدعــى عليــه األول بحيــازة ونقــل (‪)663.950‬‬\n ‫ســتمائة وثــاث وســتني ألــف وتســعمائة وخمســن حبــة مــن حبــوب‬\n ‫االمفيتامــن مــن مدينــة الريــاض إلــى مدينــة جــدة بقصــد احلصــول‬\n ‫علــى املــال وحيــازة ‪ 25‬خمســة وعشــرين حبــه مــن نفــس النــوع بقصــد‬\n ‫االســتعمال واالســتعمال مــن الســابق وللثانــي باســتقبال (‪)663.950‬‬\n ‫ســتمائة وثــاث وســتني ألــف وتســعمائة وخمســن حبــة مــن حبــوب‬\n ‫االمفيتامــن بقصــد الترويــج ـ يطلــب إثبــات مــا اســند إليهمــا واحلكــم‬\n ‫عليهمــا بالتالــي‪/1 :‬ســجنهما وجلدهمــا وتغرميهمــا اســتنادا للمــادة‬\n ‫الثامنــة والثالثــون ‪ /2‬مصــادرة الهاتفــن اجلــوال املســتخدمني يف عمليــة‬\n ‫النقــل واالســتقبال واللذيــن يحملــن الرقمــن (‪ )........‬و(‪ )........‬وفقــا‬\n\n                                                                                 ‫‪308‬‬\n\f      ‫للمــادة الثالثــة واخلمســن ‪ /3‬منعهمــا مــن الســفر خــارج البــاد بعــد‬\n      ‫تنفيــذ العقوبــة اســتناد ًا مــن املــادة السادســة واخلمســن ‪ -‬حيــث إنــه‬\n      ‫بتاريــخ ‪1434/8/25‬ه ـ تلقــت إدارة مكافحــة املخــدرات بالطائــف‬\n      ‫بالغ ـ ًا مــن قبــل اجلهــة املختصــة باملديريــة العامــة ملكافحــة املخــدرات‬\n      ‫بالريــاض مفادهــا البــاغ الــوارد ضــد املدعــى عليــه األول ويســتخدم‬\n      ‫هاتــف رقــم (‪ )...‬واملدعــى عليــه متجــه مــن الريــاض إلــى الطائــف‬\n      ‫ويرافقــه عائلتــه بقيــادة ســيارة مــن نــوع ‪ ....‬وبحوزتــه كميــة كبيــرة مــن‬\n      ‫املخــدرات وبالبحــث والتحــري لوحــظ املدعــى عليــه األول بقيــادة ســيارة‬\n      ‫مــن نــوع ‪ .....‬ومبتابعتــه مت القبــض عليــه بفنــدق ‪ .....‬وبتفتيشــه ضبــط‬\n      ‫معــه رقــم الهاتــف الــوارد بالبــاغ مــن نــوع ‪....‬وبتفتيــش الســيارة ضبــط‬\n      ‫ثــاث حقائــب قمــاش بداخلهــا (‪ )663.950‬ســتمائة وثــاث وســتني ألــف‬\n      ‫وتســعمائة وخمســن حبــة داخــل اكيــاس وضبــط حقيبــة يــد نســائية‬\n      ‫عنــد أرجــل الراكــب األمامــي وبداخلهــا (‪ )25‬خمســة وعشــرين حبــة‬\n      ‫ولوحــظ ســيارة املدعــى عليــه الثانــي وبالقبــض عليــه عثــر معــه علــى‬\n      ‫الهاتــف اجلــوال الــذي مت التنســيق عليــه وافــاد انــه مســؤول عــن كل‬\n      ‫شــيء ‪ -‬أقــر املدعــى عليــه األول مبــا جــاء يف الدعــوى وأنكــر املدعــى‬\n                                                ‫عليــه الثانــي ‪ -‬أدلــة املدعــي العــام ‪:‬‬\n      ‫‪ -‬محضــر القبــض ‪ - .‬شــهادة الشــهود ‪ - .‬وبنــاء علــى مــا ورد يف‬\n      ‫شــهادة الشــاهدين ‪ ،‬وألن إقــرار املدعــى عليــه الثانــي الــوارد يف شــهادة‬\n      ‫الشــاهدين املشــار إليــه بعاليــه ليــس صريحـ ًا يف املصادقــة علــى مــا ورد‬\n      ‫يف الدعــوى وبالتالــي فليــس كافيـ ًا يف اإلدانــة ‪ ،‬وألن بينــة املدعــي العــام‬\n      ‫غيــر موصلــة إلثبــات مــا نســب للثانــي ‪ ،‬وألن تعليــل املدعــى عليــه الثانــي‬\n      ‫ومــا ورد يف جوابــه ال ميكــن قبولــه بــل يوجــه التهمــة ضــده بصحــة مــا‬\n\n\n‫‪309‬‬\n\f‫نســب إليــه ؛ ألن شــراء التمــور ال يكــون بهــذه الطريقــة ‪ .‬ونظــر ًا لكثــرة‬\n‫جرميــة ترويــج املخــدرات وانتشــارها يف املجتمــع وتســاهل املجرمــن فيهــا‬\n‫ممــا يلــزم معــه احلــزم علــى مــن يثبــت بحقــه ذلــك وتشــديد العقوبــة بحقــه‬\n‫الســيما إذا كان الترويــج لكميــة كبيــرة ‪ -‬أوالً‪ :‬ثبــوت إدانــة املدعــى‬\n                  ‫عليــه األول ‪ ...‬بجميــع مــا نســب اليــه واحلكــم مبــا يلــي ‪:‬‬\n                                     ‫‪ -1‬بسجنه عشر سنوات من تاريخ إيقافه ‪.‬‬\n‫‪ -2‬جلــده ألفــي جلــدة مفرقــة علــى أربعــن دفعــة متســاوية يف العــدد بــن‬\n                                   ‫كل دفعــة وأخــرى مــدة ال تقــل عــن أســبوع ‪.‬‬\n                                                  ‫‪ -3‬تغرميه خمسني ألف ريال ‪.‬‬\n           ‫‪ -4‬منعه من السفر ملدة عشر سنوات بعد انتهاء محكوميته‬\n‫‪ -5‬مصــادرة اجلــوال املضبــوط بحوزتــه واملســتخدم يف هــذه القضيــة‬\n                                                        ‫واملشــار اليــه يف الدعــوى‪.‬‬\n        ‫ثاني ًا ‪ :‬توجه التهمة على املدعى عليه الثاني واحلكم مبا يلي ‪:‬‬\n                                   ‫‪ -1‬بسجنه خمس سنوات من تاريخ إيقافه ‪.‬‬\n‫‪ -2‬وجلــده خمســمائة جلــدة مفرقــة علــى عشــر دفعــات متســاوية يف‬\n               ‫العــدد بــن كل دفعــة وأخــرى مــدة ال تقــل عــن أســبوع ‪.‬‬\n‫‪ -‬قــرر املدعــي العــام االعتــراض بالئحــة واملدعــى عليهمــا االعتــراض‬\n              ‫بــدون الئحــة ‪ ،‬تصديــق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n‫احلمــد هلل وبعــد ففــي هــذا اليــوم اخلميــس املوافــق ‪1434/12/26‬هـ ـ‬\n‫الســاعة العاشــرة صباح ـ ًا لــدي أنــا ‪...... /‬القاضــي باحملكمــة اجلزائيــة‬\n‫بالطائــف وبنــاء علــى املعاملــة املقيــدة برقــم ‪342717409‬‬\n\n                                                                                        ‫‪310‬‬\n\f      ‫يف‪1434/11/27‬هـ واحملالة إلينا برقم ‪ 34535671‬يف ‪1434/11/27‬ه ـ‬\n      ‫افتتحــت اجللســة وفيهــا حضــر املدعــى العــام ‪........‬بالتعميــد رقــم ‪2367‬‬\n      ‫فـ ــي ‪1433/3/12‬هـ ـ وادعــى علـ ــى احلاضريــن باملجلــس الشــرعي ‪-1 /‬‬\n      ‫‪..........‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ............‬و‪-2‬‬\n      ‫‪................‬ســعودي اجلنســية مبوجــب الســجل رقــم (‪ )..........‬قائــا أنــه‬\n      ‫بتاريــخ ‪1434/8/25‬ه ـ تلقــت إدارة مكافحــة املخــدرات بالطائــف‬\n      ‫بالغ ـ ًا مــن قبــل اجلهــة املختصــة باملديريــة العامــة ملكافحــة املخــدرات‬\n      ‫بالريــاض مفادهــا البــاغ الــوارد ضــد املدعــى عليــه األول ويســتخدم‬\n      ‫هاتــف رقــم (‪ )........‬واملدعــى عليــه متجــه مــن الريــاض إلــى الطائــف‬\n      ‫ويرافقــه عائلتــه بقيــادة ســيارة مــن نــوع ‪ ....‬وبحوزتــه كميــة كبيــرة مــن‬\n      ‫املخــدرات وبالبحــث والتحــري لوحــظ املدعــى عليــه األول بقيــادة ســيارة‬\n      ‫مــن نــوع ‪ .....‬ومبتابعتــه مت القبــض عليــه بفنــدق ‪ ......‬وبتفتيشــه ضبــط‬\n      ‫معــه رقــم الهاتــف الــوارد بالبــاغ مــن نــوع ‪ .....‬ويرافقــه كال مــن املــرأة‬\n      ‫‪ .........../‬مت فــرز أوراق مســتقلة لهــا التهامهــا بالتســتر والفتــاة‪....... /‬‬\n      ‫واحلــدث‪.......... /‬لــم يوجــه لهمــا االتهــام لعــدم كفايــة األدلــة وبتفتيــش‬\n      ‫الســيارة ضبــط ثــاث حقائــب قمــاش بداخلهــا (‪ )663.950‬ســتمائة‬\n      ‫وثــاث وســتني ألــف وتســعمائة وخمســن حبــة داخــل اكيــاس وضبــط‬\n      ‫حقيبــة يــد نســائية عنــد أرجــل الراكــب األمامــي وبداخلها (‪ )25‬خمســة‬\n      ‫وعشــرين حبــة وأفــاد األول أن مــا مت ضبطــه عائــد لــه وأنــه حصــل عليهــا‬\n      ‫مــن شــخص ال يعرفــه بالريــاض إليصالهــا ملدينــة جــدة بالتنســيق مــع‬\n      ‫شــخص يدعــى ‪ .........../‬مت فــرز أوراق مســتقلة لــه كونــه ســجني‬\n      ‫مبحافظــة جــدة علــى هاتــف (‪)............‬مقابــل مبلــغ ‪100000‬ريــال وأن‬\n      ‫املدعــو‪ ......./‬ســيقوم بإرســال شــخص مــن طرفــه الســتالم الكميــة‬\n\n\n‫‪311‬‬\n\f‫وجــرى االنتقــال حملافظــة جــده رفــق األول ومتكينــه باالتصــال‬\n‫باملدعــو‪ .........‬علــى الهاتف(‪).............‬وعلــى مســمع مــن أفــراد الفرقــة‬\n‫وأفــاد األول بأنــه وصــل إلــى جــدة وأنــه قــام باســتئجار شــقة بشــارع ‪....‬‬\n‫بالقــرب مــن البنــك ‪ ........‬وطلــب منــه الطــرف اآلخــر ينتظــر وانــه ســوف‬\n‫يحضــر لــه شــخص ويســتلم منــه الكميــة وانتهــى االتصــال وبعدهــا ورد‬\n‫لهاتــف األول رســالة نصيــة مــن الرقــم (‪ ).........‬تضمنــت (نــص ســاعة‬\n‫ويجيلــك رجــال عنــد البنــك ويتصــل عليــك) ومت تكليــف رجــل الضبــط‬\n‫للقيــام بــدور الناقــل وورد اتصــال علــى هاتــف األول مــن الرقــم (‪).......‬‬\n‫وأفــاد املتصــل بأنــه متوقــف عنــد البنــك ‪ ........‬ولوحــظ ســيارة بقيــادة‬\n‫الثانــي وبالقبــض عليــة وبتفتيشــه ضبــط معــه الهاتــف اجلــوال الــذي مت‬\n‫التنســيق عليــه وأفــاد بأنــه مســئول عــن كل شــيء وأنــه حضــر ليســتلم‬\n‫أمانــة وعنــد ســؤاله عــن األمانــة ذكــر بأنــه يتحمــل كل شــيء وقــد‬\n‫أثبــت التقريــر الكيميائــي الشــرعي أن احلبــوب املضبوطــة حتتــوي مــادة‬\n‫االمفيتامــن احملظــورة وقــد اســفر التحقيــق عــن توجيــه االتهــام للمدعــى‬\n‫عليــه األول بحيــازة ونقــل (‪ )663.950‬ســتمائة وثــاث وســتون ألــف‬\n‫وتســعمائة وخمســون حبــة مــن حبــوب االمفيتامــن مــن مدينــة الريــاض‬\n‫إلــى مدينــة جــدة بقصــد احلصــول علــى املــال وحيازة ‪ 25‬خمســة وعشــرين‬\n‫حبــه مــن نفــس النــوع بقصد االســتعمال واالســتعمال من الســابق وللثاني‬\n‫باســتقبال (‪ )663.950‬ســتمائة وثالث وســتون ألف وتســعمائة وخمسون‬\n‫حبــة مــن حبــوب االمفيتامــن بقصــد الترويــج وبالبحــث عــن ســوابقهما‬\n‫لــم يعثــر لهمــا علــى ســوابق وحيــث أن مــا اقــدم عليــه املدعــى عليهمــا‬\n‫وهمــا بكامــل أهليتهمــا املعتبــرة شــرع ًا فعــل محــرم شــرع ًا لــذا اطلــب‬\n‫إثبــات مــا اســند إليهمــا واحلكــم عليهمــا بالتالــي‪/1 :‬ســجنهما وجلدهما‬\n\n\n                                                                                    ‫‪312‬‬\n\f      ‫وتغرميهمــا اســتنادا للمــادة الثامنــة والثالثــون ‪ /2‬مصــادرة الهاتفــن‬\n      ‫اجلــوال املســتخدمني يف عمليــة النقــل واالســتقبال واللذيــن يحملــن‬\n      ‫الرقمــن (‪ )............‬و(‪ )........‬وفقــا للمــادة الثالثــة واخلمســن ‪ /3‬منعهمــا‬\n      ‫مــن الســفر خــارج البــاد بعــد تنفيــذ العقوبــة اســتناد ًا مــن املادة السادســة‬\n      ‫واخلمســن هــذه دعــواي‪ .‬وبعــرض ذلــك علــى املدعــى عليهمــا أجــاب األول‬\n      ‫‪........‬بقولــه‪ :‬مــا ذكــره املدعــي العــام يف دعــواه مــن اتهامــي بحيــازة ونقل‬\n      ‫كميــة احلبــوب احملظــورة املذكــورة يف الدعــوى مــن الريــاض إلــى جــدة‬\n      ‫بقصــد احلصــول علــى مبلــغ مالــي قــدره ‪ 100000‬مائــة ألــف ريــال وحيــازة‬\n      ‫خمســة وعشــرين حبــة مــن نفــس النــوع بقصــد التعاطــي واننــي اســتعملت‬\n      ‫ذلــك ســابق ًا فكلــه صحيــح وقــد قمــت بذلــك بســبب احلاجــة والظــروف‬\n      ‫املاليــة الصعبــة التــي كنــت أمــر بهــا علمـ ًا باننــي عندمــا وصلــت للطائــف‬\n      ‫ومت القبــض علــي اتصلــت علــى الشــخص الــذي سأســلمه هــذه الكميــة‬\n      ‫وهــو‪......... /‬فأفادنــي بأنــه سيرســل لــي شــخص الســتالم الكميــة يف‬\n      ‫شــارع ‪ ....‬بحــي ‪ ....‬وبعــد ذلــك مت القبــض علــى املدعــى عليــه الثانــي‬\n      ‫وأفادونــي رجــال املكافحــة بأنــه هــو الشــخص الــذي حضــر الســتالم‬\n      ‫الكميــة هكــذا أجــاب كمــا أجــاب الثانــي ‪.........‬بقولــه‪ :‬مــا ذكــره‬\n      ‫املدعــي العــام يف دعــواه مــن اتهامــي باســتقبال كميــة احلبــوب املذكورة‬\n      ‫يف الدعــوى بقصــد الترويــج فغيــر صحيــح والصحيــح أننــي ذهبــت إلــى‬\n      ‫ســوق ‪ .........‬لشــراء متــور فأخبرنــي أحــد الباعــة وهــو مينــي اجلنســية أن‬\n      ‫هنــاك كميــة متــور ســتأتي إلــى الطائــف وأعطانــي رقــم الشــخص الــذي‬\n      ‫معــه التمــور فاتصلــت عليــه وطلــب منــي احلضــور لــه عنــد بنــك ‪ ........‬يف‬\n      ‫حــي ‪ .........‬شــارع ‪ .........‬فعندمــا حضــرت إلــى هنــاك مت القبــض علــي من‬\n      ‫رجــال املكافحــة واتهمونــي بذلــك هكــذا أجــاب فســألته عــن عمــا ورد‬\n\n\n‫‪313‬‬\n\f‫يف محضــر القبــض املــدون يف املعاملــة لفــه (‪ )5‬ص (‪( :)15-12‬أنــه عنــد‬\n‫القبــض عليــه جــرى ســؤاله عــن واقعــة الضبــط فأفــاد رجــال األمــن أنــه‬\n‫مســؤول عــن كل شــيء ويتحمــل كل شــيء وعنــد ســؤاله عمــن أرســله‬\n‫الســتالم تلــك الكميــة أفــاد بأنــه حضــر الســتالم أمانــة وعنــد ســؤاله‬\n‫عــن ماهيــة تلــك األمانــة قــال‪ :‬أنــا أحتمــل كل شــيء) فأجــاب بقولــه هذا‬\n‫الــكالم الــوارد يف احملضــر صحيــح ولكــن صــدر منــي بســبب االرتباك‬\n‫والضغــط النفســي والصدمــة التــي وقعــت لــي ولكننــي لــم أخبرهــم‬\n‫أننــي حضــرت الســتالم أمانــة وإمنــا ذكــرت لهــم أننــي حضــرت الســتالم‬\n‫متــر هكــذا اجــاب‪ .‬فســألت املدعــي العــام البينــة علــى دعــواه ضــد الثانــي‬\n‫فأجــاب ‪ :‬لقــد أحضــرت شــهود محضــر القبــض علــى الثانــي هكــذا‬\n‫أجــاب وقــد حضــر يف نفــس اجللســة كل مــن‪......... /‬ســعودي اجلنســية‬\n‫مبوجب الســجل املدني رقم (‪ )............‬و‪ .........‬ســعودي اجلنســية مبوجب‬\n‫الســجل املدنــي رقــم (‪ )..........‬وبســؤالهما عمــا لديهمــا مــن شــهادة شــهدا‬\n‫قائلــن‪ :‬إننــا نعمــل بــإدارة مكافحــة املخــدرات بجــدة ونشــهد هلل تعالــى‬\n‫أنــه عندمــا مت القبــض علــى املدعــى عليــه األول ‪....‬يف الطائــف مت إرســاله‬\n‫لنــا يف جــدة وعنــد حضــوره لنــا مت متكينــه مــن االتصــال علــى الشــخص‬\n‫املرســلة إليــه هــذه الكميــة مــن املخــدرات ويدعــى ‪........ /‬فاتصــل‬\n‫املدعــى عليــه ‪......‬وأخبــره أنــه أحضــر الكميــة فطلــب منــه ‪ ........‬أن‬\n‫يرتــاح هــو وأهلــه ويســكنوا قريب ـ ًا مــن شــارع ‪ .........‬يف ‪ .........‬وســوف‬\n‫يرســل لــه شــخص الســتالم األغــراض ثــم بعــد ذلــك وردت رســالة مــن‬\n‫جــوال ‪.......‬إلــى جــوال ‪......‬تتضمــن مــا نصــه (نــص ســاعة ويجيــك رجــال‬\n‫عنــد البنــك ويتصــل عليــك ) ثــم بعــد ذلــك ورد اتصــال علــى جــوال ‪.....‬‬\n‫فــرد عليــه ‪......‬فســأل املتصــل ‪......‬عــن مــكان وجــوده فأفــاده بأنــه يف‬\n\n\n                                                                                     ‫‪314‬‬\n\f      ‫شــارع ‪ .........‬قريبــا مــن البنــك ‪ ........‬فأفــاده املتصــل أنــه قريــب مــن املوقــع‬\n      ‫ثــم اتصــل مــرة أخــرى فتــم تكليــف أحــد األفــراد بالــرد فأفــاده املتصــل‬\n      ‫أنــه حاليــا بجــوار البنــك فتوجهنــا مــع الفرقــة ومعنــا املدعــى عليــه‪ .....‬إلــى‬\n      ‫موقــع البنــك فتبــن أن الــذي حضــر هــو املدعــى عليــه الثانــي ‪..........‬‬\n      ‫فأعطــى إشــارةلـ‪ .....‬أنــه عرفــه وطلــب اللحــاق بــه ويبــدو أنــه أحــس‬\n      ‫بالوضــع فتــم إيقافــه بالقــوة وعنــد القبــض عليــه ســألناه عــن ســبب‬\n      ‫حضــوره فــكان يضحــك ولــم يعطنــا إفــادة واضحــة وجازمــة عــن ســبب‬\n      ‫حضــوره فمــرة يذكــر أنــه حضــر الســتالم أمانــة ومــرة يقــول حضــرت‬\n      ‫الســتالم متــر وعنــد محاولــة اســتجوابه ملعرفــة احلقيقــة أفادنــا بأنــه‬\n      ‫مســؤول عــن كل شــيء ويتحمــل كل شــيء ولــم يعطنــا إفــادة غيــر ذلــك‬\n      ‫علمــا بأنــه بعــد القبــض علــى الثانــي تبــن أن اجلــوال الــذي معــه هــو الــذي‬\n      ‫وردت منــه االتصــاالت والرســالة الســابقة إلــى جــوال ‪.....‬كمــا أن جميــع‬\n      ‫االتصــاالت ســمعناها عــن طريــق مكبــر الصــوت هكــذا شــهدا‬\n      ‫وبعــرض ذلــك علــى املدعــى عليــه الثانــي أجــاب بقولــه مــا ذكــره الشــهود‬\n      ‫مــن إقــراري أننــي حضــرت الســتالم أمانــة فغيــر صحيــح والصحيــح هــو‬\n      ‫مــا ورد يف جوابــي هكــذا أجــاب‪ .‬ثــم أضــاف املدعــي العــام بقولــه‪ :‬ليــس‬\n      ‫لــدي زيــادة بينــة ســوى هذيــن الشــاهدين ومــا ورد يف أوراق املعاملــة‬\n      ‫هكــذا اجــاب‪ .‬فبعــد ســماعي للدعــوى وإجابــة املدعــى عليــه األول‬\n      ‫بصحــة مــا نســب إليــه فيهــا ‪ ،‬وإجابــة املدعــى عليــه الثانــي بنفــي مــا‬\n      ‫ا ذلــك مبــا جــاء يف جوابــه ‪ ،‬وبنــاء علــى مــا ورد يف‬    ‫نســب اليــه فيهــا معلـ ً‬\n      ‫شــهادة الشــاهدين ‪ ،‬وألن إقــرار املدعــى عليــه الثانــي الــوارد يف شــهادة‬\n      ‫الشــاهدين املشــار إليــه بعاليــه ليــس صريحـ ًا يف املصادقــة علــى مــا ورد‬\n      ‫يف الدعــوى وبالتالــي فليــس كافيـ ًا يف اإلدانــة ‪ ،‬وألن بينــة املدعــي العــام‬\n\n\n‫‪315‬‬\n\f‫غيــر موصلــة إلثبــات مــا نســب للثانــي ‪ ،‬وألن تعليــل املدعــى عليــه الثانــي‬\n‫ومــا ورد يف جوابــه ال ميكــن قبولــه بــل يوجــه التهمــة ضــده بصحــة مــا‬\n‫نســب إليــه ؛ ألن شــراء التمــور ال يكــون بهــذه الطريقــة ‪ ،‬وإلقــراره‬\n‫باالتصــال علــى شــخص واحلضــور لــه يف نفــس املــكان الــذي ذكــره‬\n‫املدعــو‪ ........./‬للمدعــى عليــه األول ‪ ،‬إضافــة إلــى مــا ورد يف شــهادة‬\n‫الشــاهدين مــن إقــراره أمامهــم بعــد القبــض عليــه بأنــه حضــر الســتالم‬\n‫أمانــة وأنــه مســؤول عــن كل شــيء ‪ ،‬كمــا أن عــدم إفصاحــه عنــد‬\n‫القبــض عليــه عمــن أرســله يوجــه التهمــة ضــده أيضــا ‪ ،‬وبعــد االطــاع‬\n‫علــى أوراق املعاملــة مبــا فيهــا محضــري القبــض والتفتيــش املرصــود‬\n‫مضمونهمــا يف الدعــوى والتقريــر الكيميائــي الشــرعي املتضمــن‬\n‫إيجابيــة العينــات املضبوطــة ملــادة االمفيتامــن احملظــورة ‪ ،‬وبنــاء علــى‬\n‫املــواد (الثامنــة والثالثــن) و(احلاديــة واألربعــن) و(الثالثــة واخلمســن)‬\n‫و(السادســة واخلمســن) و(الثانيــة والســتني) مــن نظــام مكافحــة‬\n‫املخــدرات ‪ ،‬وخلطــورة مــا قــام بــه املدعــي عليــه األول وبشــاعته ونظــر ًا‬\n‫لكثــرة جرميــة ترويــج املخــدرات وانتشــارها يف املجتمــع وتســاهل‬\n‫املجرمــن فيهــا ممــا يلــزم معــه احلــزم علــى مــن يثبــت بحقــه ذلــك وتشــديد‬\n‫العقوبــة بحقــه الســيما إذا كان الترويــج لكميــة كبيــرة وعلــى نطــاق‬\n‫واســع يف املجتمــع وألن فعــل املدعــى عليــه االول فيــه توســيع لنطــاق‬\n‫ترويــج املخــدرات وألن الكميــة املضبوطــة مــع املدعــى عليــه األول‬\n‫كبيــرة جــد ًا ويحصــل بســببها إفســاد مجتمــع بأكملــه وألن مــا قــام بــه‬\n‫املدعــى عليــه االول يعتبــر مــن اإلفســاد يف األرض كمــا أنــه يــدل علــى‬\n‫تســاهله يف إفســاد املجتمــع مقابــل احلصــول علــى مصلحــة شــخصية‬\n‫وألنــه قصــد مــن جرميتــه احلصــول علــى املــال وبنــاء علــى مــا قــرره الفقهــاء‬\n\n\n                                                                                         ‫‪316‬‬\n\f      ‫مــن مشــروعية معاملــة اجلانــي بنقيــض قصــده ‪ ،‬وألن املدعــى عليــه األول‬\n      ‫أظهــر التوبــة والنــدم ‪ ،‬وألن املدعــى عليهمــا ليــس لهمــا ســوابق ‪ ،‬لهــذا‬\n      ‫كلــه فقــد صــدر منــي مــا يلــي‪ :‬أوالً‪ :‬ثبــت لــدي إدانــة املدعــى عليــه‬\n      ‫األول‪........‬بجميــع مــا نســب اليــه وحكمــت عليــه لقــاء ذلــك بســجنه‬\n      ‫عشــر ســنوات مــن تاريــخ إيقافــه ‪ ،‬وجلــده ألفــي جلــدة مفرقــة علــى‬\n      ‫أربعــن دفعــة متســاوية يف العــدد بــن كل دفعــة وأخــرى مــدة ال تقــل عــن‬\n      ‫أســبوع ‪ ،‬وتغرميــه خمســن ألــف ريــال ‪ ،‬ومنعــه مــن الســفر ملــدة عشــر‬\n      ‫ســنوات بعــد انتهــاء محكوميتــه ‪ ،‬ومصــادرة اجلــوال املضبــوط بحوزتــه‬\n      ‫واملســتخدم يف هــذه القضيــة واملشــار اليــه يف الدعــوى‪ .‬ثاني ـاً‪ :‬لــم تثبــت‬\n      ‫لــدي إدانــة املدعــى عليــه الثاني‪......‬باســتقبال كميــة احلبــوب احملظــورة‬\n      ‫الــواردة يف الدعــوى بقصــد الترويــج وإمنــا تتوجــه التهمــة ضــده بذلــك‬\n      ‫وحكمــت عليــه لقــاء ذلــك بســجنه خمــس ســنوات مــن تاريــخ إيقافــه ‪،‬‬\n      ‫وجلــده خمســمائة جلــدة مفرقــة علــى عشــر دفعــات متســاوية يف العــدد‬\n      ‫بــن كل دفعــة وأخــرى مــدة ال تقــل عــن أســبوع ‪ ،‬وصرفــت النظــر عــن‬\n      ‫بقيــة طلبــات املدعــي العــام املتعلقــة باملدعــى عليــه الثانــي لعــدم ثبــوت‬\n      ‫إدانتــه مبــا نســب إليــه هــذا مــا ظهــر لــي وبــه حكمــت وبعــرض ذلــك‬\n      ‫علــى املدعــى عليهمــا قــررا االعتــراض بــدون لوائــح اعتراضيــة وأمــا‬\n      ‫املدعــي العــام فقــرر االعتــراض بالئحــة فجــرى تســليمه نســخة مــن‬\n      ‫احلكــم يف نفــس اليــوم وإفهامــه بتعليمــات االســتئناف ففهــم ذلــك ‪،‬‬\n      ‫وصلــى اهلل وســلم علــى ســيدنا محمــد وعلــى آلــه وصحبــه أجمعــن حــرر‬\n                                                                 ‫يف ‪1434/12/26‬هـ ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد ففــي هذا اليوم اخلميــس املوافق ‪1435/01/25‬هـ‬\n      ‫افتتحــت اجللســة وقــد وردتنــا املعاملــة مــن محكمــة االســتئناف وبرفقهــا‬\n\n\n‫‪317‬‬\n\f‫قــرار الدائــرة اجلزائيــة اخلامســة رقــم (‪ )35113824‬يف ‪1435/01/14‬ه ـ‬\n‫املتضمــن املصادقــة علــى احلكــم ‪ ،‬وللمعلوميــة جــرى حتريــر ذلــك ‪،‬‬\n       ‫وصلــى اهلل وســلم علــى نبينــا محمــد‪ .‬حــرر يف ‪1435/01/25‬هــ‪.‬‬\n\n\n\n\n                                                                          ‫‪318‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"c99e10bc-04e4-545e-ba4d-827d4f791349","source_page_start":308,"source_page_end":318,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"b3a01ca9c87fe74b654401bfa3aede4af4613cd0277bb79264bdd037ae7360d6","normalized_text_hash":"f866add56204509dc6e1852dd0cd015e67d141a255d5fcf3cc7e74751ce96dee","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v21-p308-34390103"},{"id":"8e8cec43-5d5f-5cce-a4ac-dc7036e5c3a5","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة بقصد التعاطي والترويج -قات -هروب من رجال األمن -املدعى عليه حدث -قلة الكمية املضبوطة -تداخل العقوبات التعزيرية -التعزير باحلبس.","document_number":"34380001","case_number":"34541322","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/11/27","year":"1434","subject":"مخدرات -حيازة بقصد التعاطي والترويج -قات -هروب من رجال األمن -املدعى عليه حدث -قلة الكمية املضبوطة -تداخل العقوبات التعزيرية -التعزير باحلبس.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 34380001:‬تاريخه‪1434/11/27:‬هـ‬\n                          ‫رقم القضية‪34541322:‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                   ‫‪ 35104264‬تاريخه‪1435/1/3:‬هـ‬\n\n\n       ‫مخــدرات ‪ -‬حيــازة بقصــد التعاطــي والترويــج ‪ -‬قــات ‪ -‬هــروب مــن‬\n       ‫رجــال األمــن ‪-‬املدعــى عليــه حــدث ‪ -‬قلــة الكميــة املضبوطــة ‪ -‬تداخــل‬\n                                  ‫العقوبــات التعزيريــة ‪ -‬التعزيــر باحلبــس‪.‬‬\n\n\n\n       ‫‪ -1‬مــا قــرره أهــل العلــم يف تداخــل العقوبــات التعزيريــة حيــث جــاء‬\n       ‫يف كشــاف القنــاع ج ‪ 485/ 20‬للبهوتــي ( ولــو توجــه عليــه تعزيــرات‬\n       ‫علــى معــاص شــتى فــإن متحضــت هلل تعالــى واحتــد نوعهــا كأن قبــل‬\n       ‫أجنبيــة مــرارا أو اختلــف نوعهــا بــأن قبــل أجنبيــة وملــس أخــرى قصــدا‬\n                                             ‫تداخلــت وكفــاه تعزيــر واحــد ) ‪.‬‬\n       ‫‪ -2‬تعميــم وزيــر الداخليــة رقــم ( ‪ ) 16/13074‬يف ‪1422/2/15‬ه ـ املبنــي‬\n                    ‫علــى مــا صــدر مــن وزارة العــدل برقــم ‪ 310‬يف ‪1394/4/7‬ه ـ ‪.‬‬\n             ‫‪ -3‬تعميم نائب وزير الداخلية رقم (‪ )16/27301‬يف ‪1418/4/21‬هـ‬\n\n\n\n\n       ‫ادعــى املدعــي العــام ضــد املدعــى عليــه (حــدث) بحيــازة قــات بقصــد‬\n       ‫الترويــج والتعاطــي والهــروب مــن رجــال األمــن والتســتر علــى مصــدر مــا‬\n       ‫مت ضبطــه و طلــب إثبــات مــا أســند إليــه واحلكــم عليــه بعقوبــة تعزيريــة‬\n       ‫‪ .‬أثنــاء قيــام الدوريــة األمنيــة مبهامهــا أقبلــت ســيارة مســرعة يقودهــا‬\n\n‫‪319‬‬\n\f‫املدعــى عليــه وعنــد االشــتباه بــه طلــب منــه التوقــف فــاذ بالفــرار ويف‬\n‫أحــد الطــرق اســتطاع املدعــى عليــه إيقــاف الســيارة والهــروب وبتفتيــش‬\n‫الســيارة عثــر بهــا علــى كميــة مــن نبــات القــات ثــم حضــر صاحــب‬\n‫الســيارة إلــى مقــر املكافحــة وبرفقتــه احلدث املدعى عليــه وأقر بقيادته‬\n‫للســيارة ‪ ،‬وأثبــت التقريــر الكيميائــي الشــرعي إيجابيــة العينــة لنبــات‬\n‫القــات احملظــور وصــادق املدعــى عليــه علــى مــا هــو منســوب إليــه ‪ ،‬وملــا‬\n‫كانــت بينــة املدعــي العــام علــى الترويــج كبــر الكميــة املضبوطــة ممــا‬\n‫ترتــب عليــه عــدم ثبــوت اإلدانــة علــى املدعــى عليــه بحيــازة القــات بقصــد‬\n‫الترويــج وبالتســتر علــى مصــدر مــا مت ضبطــه وصــرف النظــر عــن‬\n‫طلــب املدعــي العــام مجازاتــه لقــاء ذلــك ‪،‬وبنــاء علــى مــا تقــدم حكمــت‬\n‫احملكمــة بتعزيــره لقــاء ذلــك بالســجن خمســة أشــهر وتخفيــف العقوبــة‬\n‫نظــر ًا لصغــر ســنه وملــا ظهــر عليــه مــن النــدم والتوبــة وقنــع املدعــى عليــه‬\n‫وصــدق احلكــم مــن‬    ‫باحلكــم واعتــرض املدعــي العــام بــدون الئحــة ُ‬\n                                                           ‫محكمــة االســتئناف‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده أمــا بعــد فلــدي أنــا ‪.....‬القاضــي باحملكمــة اجلزائيــة‬\n‫بجــازان واملكلــف بنظــر قضايــا األحــداث مبوجــب مــا ورد مــن فضيلــة‬\n‫الرئيــس برقــم (‪ )342551458‬وتاريــخ ‪1434/11/10‬ه ـ وبنــاء علــى‬\n‫املعاملــة الــواردة مــن دائــرة االدعــاء العــام بجــازان واملقيــدة بــوارد‬\n‫احملكمــة برقــم (‪ )342747456‬وتاريــخ ‪1434/12/2‬ه ـ واحملالــة مــن‬\n‫فضيلــة الرئيــس برقــم (‪ )34541322‬وتاريــخ ‪1434/12/2‬ه ـ واملتعلقــة‬\n‫بدعــوى املدعــي العــام ضــد احلــدث ‪ .....‬املتهــم يف قضيــة حيــازة كميــة‬\n\n                                                                                          ‫‪320‬‬\n\f      ‫مــن نبــات القــات عليــه ففــي هــذا اليوم األربعــاء ‪1434/12/4‬ه ـ افتتحت‬\n      ‫اجللســة األولــى يف متــام الســاعة احلاديــة عشــرة والنصــف وفيهــا حضــر‬\n      ‫املدعــي العــام ‪.....‬املوجــه باخلطــاب رقــم (‪ ).....‬وتاريــخ ‪1434/8/29‬ه ـ‬\n      ‫وادعــى علــى احلاضــر احلــدث ‪17(.....‬عامــا) ســعودي اجلنســية مبوجــب‬\n      ‫الســجل املدنــي رقــم (‪ ).....‬أنــه بتاريــخ ‪1434/7/7‬ه ـ وأثنــاء قيــام إحــدى‬\n      ‫دوريــات قيــادة الفرقــة األولــى بالطــوال مبهامهــا وأثنــاء جتولهــم يف‬\n      ‫املوقــع املســمى مثلــث ‪.....‬أقبلــت عليهــم ســيارة مــن نــوع ‪ .......‬مــن صنــع‬\n      ‫عــام (‪2003‬م) حتمــل اللوحــة رقــم (‪ )..........‬تعــود للمواطــن ‪(.....‬مت‬\n      ‫اتخــاذ اإلجــراء النظامــي حيالهــا) وكانــت تســير بســرعة عاليــة وعنــد‬\n      ‫اشــتباه الدوريــة بوضــع قائدهــا مت طلــب اســتيقافه إال أنــه الذ بالفــرار‬\n      ‫وباإلبــاغ عنــه عبــر اجلهــاز بقيــادة الفرقــة متــت مطاردتــه واســتمرت إلــى‬\n      ‫أن وصلــت إلــى قريــة ‪.....‬ومــن ثــم لقريــة الوتــد ويف أحــد الطــرق اســتطاع‬\n      ‫قائــد الســيارة التوقــف وفتــح البــاب والذ بعدهــا بالفــرار قبــل أن تصــل‬\n      ‫الدوريــة إليــه واختفــى عــن األنظــار وبتفتيــش الســيارة مت ضبــط كميــة‬\n      ‫مــن نبــات القــات احملظــور كانــت مخبــأة خلــف مقعــدة الراكــب‬\n      ‫والســائق بشــكل واضــح حيــث متكــن مشــاهدتها وبلــغ وزن الكميــة‬\n      ‫املضبوطــة (‪19‬كجــم) تســعة عشــر كيلــو جــرام وقــد مت تفتيــش‬\n      ‫محتويــات الســيارة ومت ضبــط اســتمارة الســيارة ومشــهد تعريــف بوجــود‬\n      ‫معاملــة باســم كل مــن ‪.....‬و‪ .....‬ومحفظــة بنيــة اللــون حتتــوي علــى صــورة‬\n      ‫بطاقــة أحــوال باســم املدعــى عليــه ومت ضبــط بطاقــة شــهادة صحيــة‬\n      ‫وكــرت شــريحة لالتصــاالت الســعودية وثــاث شــرائح لشــركات‬\n      ‫مينيــة وبتاريــخ ‪1434/7/30‬ه ـ يف متــام الســاعة احلاديــة عشــرة والنصــف‬\n      ‫حضــر املواطــن ‪.....‬ملقــر مكافحــة املخــدرات مبحافظــة ‪.....‬وأفــاد أن‬\n\n\n‫‪321‬‬\n\f‫لــه ســيارة مــن نــوع ‪( ...‬املذكــورة أوصافهــا أعــاه) مت القبــض عليهــا‬\n‫وبهــا كميــة مــن نبــات القــات احملظــور وقــد قــام بإعطائهــا املدعــى عليــه‬\n‫الــذي حضــر معــه وأفــاد املدعــى عليــه بأنــه مــن كان يقــود الســيارة بعــد‬\n‫أن الذ بالفــرار والكميــة املضبوطــة مــن نبــات القــات تعــود لــه وليــس‬\n‫ملالــك الســيارة أي عالقــة أو علــم بذلــك وأثبــت التقريــر الكيميائــي‬\n‫الشــرعي رقــم (‪ ).....‬وتاريــخ ‪ 1434/5/12‬ه ـ الصــادر مــن مركــز‬\n‫مراقبــة الســموم والكيميــاء الطبيــة الشــرعية بجــازان إيجابيــة العينــة‬\n‫املرســلة مــن الكميــة املضبوطــة لنبــات القــات احملظــور املــدرج علــى‬\n‫اجلــدول رقــم (‪ )4‬امللحــق بنظــام مكافحــة املخــدرات واملؤثــرات العقليــة‬\n‫الصــادر باملرســوم امللكــي رقــم م‪ 39/‬وتاريــخ ‪1426/7/8‬ه ـ ومت إيقافــه‬\n‫بــدار املالحظــة االجتماعيــة بنــاء ًا علــى توجيــه فضيلــة قاضــي األحــداث‬\n‫وباســتجواب املدعــى عليــه ومواجهتــه بالتهمــة املنســوبة إليــه أقــر‬\n‫بحيازتــه للكميــة املضبوطــة مــن نبــات القــات احملظــور وذكــر بأنهــا‬\n‫تعــود لــه شــخصي ًا وغرضــه مــن ذلــك االســتخدام الشــخصي وبالبحــث‬\n‫عــن ســوابقه لــم يعثــر لــه علــى ســوابق مســجلة حتــى تاريخــه وقــد أســفر‬\n‫التحقيــق معــه عــن توجيــه االتهــام إليــه بحيــازة مــا وزنــه (‪19‬كجــم)‬\n‫تســعة عشــر كيلــو جــرام مــن نبــات القــات احملظــور بقصــد التعاطــي‬\n‫والترويــج وهروبــه مــن رجــال األمــن وتســتره علــى مصــدر الكميــة‬\n‫وألن مــا أقــدم عليــه املذكــور فعــل محــرم شــرع ًا ومعاقــب عليــه نظامـ ًا‬\n‫مبوجــب قــرار مجلــس الــوزراء رقــم (‪ )11‬لعــام ‪1374‬ه ـ ومــا حلــق بــه مــن‬\n‫تعديــات فقــد طلــب املدعــي العــام النظــر يف قضيتــه شــرع ًا واحلكــم‬\n‫عليــه بعقوبــة تعزيريــة زاجــرة لقــاء مــا أســند إليــه وبعــرض دعــوى املدعــي‬\n‫العــام علــى املدعــى عليــه صــدق هربــه مــن رجــال األمــن والقبــض علــى‬\n\n\n                                                                                      ‫‪322‬‬\n\f      ‫الســيارة التــي كانــت بقيادتــه يف الزمــان واملــكان املشــار إليهمــا وبهــا‬\n      ‫كميــة القــات املذكــورة وقــرر أن قصــده مــن حيازتــه لنبــات القــات هــو‬\n      ‫االســتعمال الشــخصي وأنكــر قصــد الترويــج وأضــاف قائــا حصلــت‬\n      ‫علــى نبــات القــات مــن شــخص مينــي ال يعرفــه يكنــى ب‪.....‬يف قريــة ‪.....‬‬\n      ‫بثالثمائــة ريــال هكــذا أجــاب عنــد ذلــك جــرى ســؤال املدعــي العــام هــل‬\n      ‫لديــك بينــة علــى قصــد املدعــى عليــه للترويــج وتســتره علــى مصــدر مــا‬\n      ‫ا بينتــي مــا يف أوراق املعاملــة‬   ‫مت ضبطــه مــن نبــات القــات فأجــاب قائ ـ ً‬\n      ‫إضافــة إلــى كبــر حجــم الكميــة املضبوطــة هكــذا أجــاب وبالرجــوع‬\n      ‫إلــى أوراق املع ــاملة جــرى االطــاع علــى التقريــر الكيميائــي الشــرعي‬\n      ‫وثبــت ســوابق املدعــى عليــه فوجــدت مطابقــة ملــا يف الدعــوى كمــا جــرى‬\n      ‫االطــاع علــى بقيــة لفــات املعاملــة ولــم أجــد بهــا مــا يديــن املدعــى عليــه‬\n      ‫بقصــد الترويــج ســوى قرينــة كبــر حجــم الكميــة ولــم أجد بهــا ما يثبت‬\n      ‫إدانــة املدعــى عليــه بالتســتر علــى مصــدر كميــة القــات املضبوطــة عنــد‬\n      ‫ا‬\n      ‫ذلــك جــرى ســؤال املدعــي العــام هــل لديــك مزيــد بينــة فأجــاب قائ ـ ً‬\n      ‫ال أعلــم لــي مزيــد بينــة هكــذا أجــاب عليــه فبنــاء علــى مــا تقــدم مــن‬\n      ‫الدعــوى واإلجابــة ولعجــز املدعــي العــام عــن إقامــة البينــة املثبتــة إلدانــة‬\n      ‫املدعــى عليــه بقصــد الترويــج وتســتره علــى مصــدر كميــة نبــات القــات‬\n      ‫املضبوطــة وملــا تضمنتــه التعليمــات مــن أنــه ال جتــوز معاقبــة األحــداث‬\n      ‫بــأي نظــام وإمنــا يحالــون لقاضــي محكمــة األحــداث لتقريــر مــا يجــب‬\n      ‫يف حقهــم يف جميــع القضايــا عــدا القضايــا التــي فيهــا قطــع أو رجــم أو‬\n      ‫قتــل فهــذه تنظــر مــن قبــل احملكمــة املختصــة كمــا جــاء يف تعميم ســمو‬\n      ‫وزيــر الداخليــة رقــم (‪ ) 13074/16‬وتاريــخ ‪1422/2/15‬ه ـ املبنــي علــى‬\n      ‫مــا صــدر عــن وزارة العــدل برقــم (‪ ) 310‬وتاريخ‪1394/4/7‬ه ـ وجــاء‬\n\n\n‫‪323‬‬\n\f‫بذلــك أيضــا يف قضايــا تهريــب الســاح مــن قبــل األحــداث تعميــم ســمو‬\n‫نائــب وزيــر الداخليــة رقــم (‪ ) 76791/16‬وتاريــخ ‪1420/11/10‬ه ـ ويف‬\n‫قضايــا األحــداث املروريــة تعميــم ســمو وزيــر الداخلية رقــم( ‪24833/16‬‬\n‫) وتاريــخ ‪1426/3/14‬ه ـ ويف قضايــا تهريــب األشــخاص والتســلل‬\n‫إلــى داخــل أراضــي اململكــة برقيــة ســمو رئيــس رئاســة ديــوان مجلــس‬\n‫الــوزراء رقــم (‪/56101‬ب) وتاريــخ ‪1427/12/20‬ه ـ الــواردة بتعميــم‬\n‫ســمو وزيــر الداخليــة رقــم (‪/1‬ب‪ )4780/2/‬وتاريــخ ‪1428/1/12‬ه ـ‬\n‫كمــا جــاء يف قضايــا الرشــوة والتزويــر خطــاب معالــي رئــس ديــوان‬\n‫املظالــم رقــم (‪ )6/19‬وتاريــخ ‪1402/11/20‬ه ـ املتضمــن أن قضــاء‬\n‫ديــوان املظالــم اســتقر فيمــا يتعلــق مبحاكمــة املتهمــن األحــداث عــن‬\n‫جرائــم الرشــوة والتزويــر أن االختصــاص يف شــأنها ينعقــد حملكمــة‬\n‫األحــداث كمــا صــدرت يف هــذا الشــأن موافقــة املقــام الســامي برقــم‬\n‫(‪ )23383/4‬وتاريــخ ‪1402/10/2‬ه ـ ويف قضايــا األحــداث املتعلقــة‬\n‫بانتحــال صفــة رجــل الســلطة العامــة صــدر قــرار ديــوان املظالــم رقــم‬\n‫(‪/291‬د‪/‬ج‪ )8/‬لعــام ‪1417‬ه ـ وصــدر توجيــه ســمو نائــب وزيــر الداخليــة‬\n‫باخلطــاب رقــم(‪ )27301/16‬وتاريــخ ‪1418/4/21‬ه ـ املتضمــن إحالــة‬\n‫حدثــن إلــى قاضــي األحــداث للنظــر فيهــا بالوجــه الشــرعي واعتبــار‬\n‫هــذا قاعــدة عامــة يف جميــع احلــاالت املماثلــة لذلــك كلــه فقــد قــررت‬\n‫مــا يلــي أوال لــم تثبــت لــدي إدانــة املدعــى عليــه بقصــد الترويــج وصرفــت‬\n‫النظــر عــن طلــب املدعــي العــام إثبــات إدانــة املدعــى عليــه ومجازاتــه لقــاء‬\n‫ذلــك ثانيــا لــم تثبــت لــدي إدانــة املدعــى عليــه بالتســتر علــى مصــدر مــا‬\n‫مت ضبطــه مــن نبــات القــات وصرفــت النظــر عــن طلــب املدعــي العــام‬\n‫إثبــات إدانــة املدعــى عليــه ومجازاتــه لقــاء ذلــك ثالثــا ثبتــت لــدي إدانــة‬\n\n\n                                                                                        ‫‪324‬‬\n\f      ‫املدعــى عليــه بالهــرب مــن رجــال األمــن وهــو يســتحق العقوبــة التعزيريــة‬\n      ‫لقــاء ذلــك رابعــا ثبتــت لــدي إدانــة املدعــى عليــه بحيــازة كميــة القــات‬\n      ‫املذكــورة أعــاه بقصــد التعاطــي وهــو يســتحق العقوبــة التعزيريــة‬\n      ‫لقــاء ذلــك وملــا قــرره أهــل العلــم يف تداخــل العقوبــات التعزيريــة قــال‬\n      ‫العالمــة البهوتــي (ولــو توجــه عليــه تعزيــرات علــى معــاص شــتى فــإن‬\n      ‫متحضــت هلل تعالــى واحتــد نوعهــا كأن قبــل أجنبيــة مــرار ًا أو اختلــف‬\n      ‫نوعهــا بــأن قبــل أجنبيــة وملــس أخــرى قصــد ًا تداخلــت وكفــاه تعزيــر‬\n      ‫واحــد) كشــاف القنــاع عــن مــن اإلقنــاع (ج‪20‬ص‪ )485‬لذلــك كلــه‬\n      ‫فقــد قــررت االكتفــاء مبجــازاة املدعــى عليــه لقــاء حيازتــه لنبــات القــات‬\n      ‫بقصــد االســتخدام الشــخصي ونظــرا لكبــر حجــم الكميــة فــإن ذلــك‬\n      ‫يوجــه إليــه الشــبهة بقصــد الترويــج غيــر أنــه ولصغــر ســنه وملــا ظهــر‬\n      ‫عليــه مــن النــدم فقــد حكمــت عليــه لذلــك باحلبــس مــدة خمســة أشــهر‬\n      ‫تبــدأ مــن تاريــخ إيقافــه علــى ذمــة هــذه القضيــة يف ‪1434/7/30‬ه ـ هــذا‬\n      ‫مــا ثبــت لــدي وبــه حكمــت وبعرضــه علــى الطرفــن قــرر املدعــي العــام‬\n      ‫معارضتــه وطلــب رفعــه حملكمــة االســتئناف دون الئحــة فأجبتــه لذلــك‬\n      ‫وقــرر املدعــى عليــه القناعــة بــه وقــد جــرى النطــق بــه يف متــام الســاعة‬\n      ‫الثانيــة عشــرة إال ربعــا وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا‬\n                        ‫محمــد وآلــه وصحبــه أجمعــن حــرر يف ‪1434/12/4‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة الرابعــة‬\n      ‫لتدقيــق القضايــا اجلزائيــة مبحكمــة االســتئناف مبنطقــة عســير علــى‬\n      ‫املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة بجــازان برقــم‬\n      ‫‪ 342747456‬وتاريــخ ‪1434/12/22‬ه ـ املرفــق بهــا القــرار الصــادر مــن‬\n      ‫فضيلــة القاضــي باحملكمــة الشــيخ ‪..... /‬برقــم ‪ 34380001‬وتاريــخ‬\n\n\n‫‪325‬‬\n\f‫‪1434/11/27‬ه ـ اخلــاص بدعــوى املدعــي العــام ض ـ ـ ـ ـ ــد ‪..... /‬يف قضيــة‬\n‫( قــات ) علــى الصفــة املوضحــة يف القــرار املتضمــن حكــم فضيلتــه‬\n‫مبــا هــو مــدون ومفصــل فيــه وبدراســة القــرار وصــورة ضبطــه وأوراق‬\n‫املعاملــة تقــررت املوافقــة علــى احلكــم واهلل املوفــق وصلــى اهلل علــى‬\n                                             ‫نبينــا محمــد وآلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                      ‫‪326‬‬\n\f                       ‫كشاف املوضوعات‬\n\n‫الصفحة‬                      ‫املوضوع‬                        ‫التصنيف‬   ‫م‬\n\n\n         ‫دعوى عامة بتعزير املدعى عليه حليازته ثالث حبات‬\n  ‫‪5‬‬        ‫من اإلمفيتامني بقصد التعاطي وتعاطيه منها‬         ‫حيازة‬    ‫‪1‬‬\n         ‫والجتاره باألشخاص من خالل النقل بني مدينتني‬\n\n\n         ‫دعوى عامة بتعزير املدعى عليه (مقيم) حليازته تسع‬\n  ‫‪11‬‬      ‫حبات من الترامادول احملظور لقصد االستعمال‬         ‫حيازة‬    ‫‪2‬‬\n                         ‫وتعاطي احلشيش‬\n\n\n           ‫دعوى عامة بتعزير املدعى عليه حليازته سيجارة‬\n  ‫‪17‬‬                                                        ‫حيازة‬    ‫‪3‬‬\n                ‫ممزوجة باحلشيش بقصد التعاطي‬\n\n\n           ‫دعوى عامة بتعزير املدعى عليه حليازته احلبوب‬\n  ‫‪21‬‬        ‫احملظورة واحلشيش بقصد التعاطي وتعاطيه‬           ‫حيازة‬    ‫‪4‬‬\n           ‫للحشيش وإدخال ما بحوزته منهما إلى السجن‬\n\n\n          ‫دعوى عامة بتعزير املدعى عليه حليازته قطع ًا من‬\n          ‫احلشيش بقصد االجتار والشروع يف بيع قطعتني‬\n  ‫‪26‬‬                                                        ‫حيازة‬    ‫‪5‬‬\n         ‫من احلشيش بقصد االجتار والشروع يف بيع احلشيش‬\n                               ‫وتعاطيه‬\n\n\n          ‫دعوى عامة بتعزير املدعى عليه حليازته ‪ 170‬حبة‬\n  ‫‪36‬‬      ‫من اإلمفيتامني بقصد التعاطي والترويج وحليازته‬     ‫حيازة‬    ‫‪6‬‬\n                ‫احلشيش بقصد التعاطي وتعاطيه منه‬\n\n\n         ‫دعوى عامة بتعزير املدعى عليه حليازته قطعة دون‬\n          ‫الوزن من احلشيش وسيجارة مخلوطة به بقصد‬\n  ‫‪41‬‬                                                        ‫حيازة‬    ‫‪7‬‬\n         ‫التعاطي وحيازة مفتاح حتتوى غسالته على احلشيش‬\n                       ‫وتعاطيه للحشيش‬\n\f‫الصفحة‬                     ‫املوضوع‬                      ‫التصنيف‬   ‫م‬\n\n\n          ‫دعوى عامة بتعزير املدعى عليه حليازته احلبوب‬\n         ‫احملظورة بقصد التعاطي واإلهداء وتعاطيه لها‬\n  ‫‪46‬‬                                                     ‫حيازة‬    ‫‪8‬‬\n         ‫والشروع يف إهدائها ومحاولة إدخالها إلى غرفة‬\n                             ‫التوقيف‬\n\n\n         ‫دعوى عامة بتعزير املدعى عليه حليازته األفيون‬\n  ‫‪54‬‬                                                     ‫حيازة‬    ‫‪9‬‬\n                        ‫وتعاطيه للهيروين‬\n\n\n         ‫دعوى عامة بتعزير املدعى عليه حليازته احلشيش‬\n  ‫‪60‬‬                                                     ‫حيازة‬    ‫‪10‬‬\n            ‫بقصد التعاطي وإدخاله إلى السجن‬\n\n\n          ‫دعوى عامة بتعزير املدعى عليه حليازته حبوب‬\n  ‫‪66‬‬                                                     ‫حيازة‬    ‫‪11‬‬\n             ‫الزنكس احملظورة بقصد التعاطي‬\n\n\n         ‫دعوى عامة بتعزير املدعى عليه حليازته حبة من‬\n  ‫‪72‬‬     ‫احلبوب احملظورة بقصد التعاطي وتعاطيه منها‬       ‫حيازة‬    ‫‪12‬‬\n                 ‫وقيادة السيارة حتت تأثيرها‬\n\n\n         ‫دعوى عامة بتعزير املدعى عليه لترويجه احلبوب‬\n  ‫‪78‬‬     ‫املخدرة عن طريق البيع وحيازتها لقصد الترويج‬     ‫حيازة‬    ‫‪13‬‬\n                         ‫وتعاطيه منها‬\n\n\n         ‫دعوى عامة بتعزير املدعى عليه حليازته احلشيش‬\n  ‫‪87‬‬                                                     ‫حيازة‬    ‫‪14‬‬\n                  ‫بقصد الترويج وتعاطيه له‬\n\n\n          ‫دعوى عامة بتعزير املدعى عليه(مقيم)لشرائه‬\n          ‫وحيازته احلشيش وسيجارة ممزوجة باحلشيش‬\n  ‫‪95‬‬                                                     ‫حيازة‬    ‫‪15‬‬\n          ‫وخمس حبات من الترامادول بقصد التعاطي‬\n               ‫وتعاطيه لهما وتستره على املصدر‬\n\f‫الصفحة‬                      ‫املوضوع‬                        ‫التصنيف‬   ‫م‬\n\n\n           ‫دعوى عامة بتعزير املدعى عليه حليازته احلبوب‬\n ‫‪101‬‬     ‫احملظورة لغير قصد الترويج أو التعاطي وتستره على‬    ‫حيازة‬    ‫‪16‬‬\n                ‫املصدر وهروبه من الفرقة القابضة‬\n\n\n           ‫دعوى عامة بتعزير املدعى عليه حليازته احلبوب‬\n ‫‪106‬‬       ‫احملظورة (اإلمفيتامني والكلونازيبام) بقصد‬        ‫حيازة‬    ‫‪17‬‬\n                       ‫التعاطي وتعاطيه لها‬\n\n\n           ‫دعوى عامة بتعزير املدعى عليه حليازته احلشيش‬\n ‫‪112‬‬                                                        ‫حيازة‬    ‫‪18‬‬\n                          ‫بقصد التعاطي‬\n\n\n         ‫دعوى عامة بتعزير املدعى عليه حليازته الكوكايني‬\n ‫‪117‬‬                                                        ‫حيازة‬    ‫‪19‬‬\n            ‫بقصد الترويج وشروعه يف بيعه بقصد االجتار‬\n\n\n         ‫دعوى عامة بتعزير املدعى عليه حليازته القات بقصد‬\n ‫‪124‬‬                                                        ‫حيازة‬    ‫‪20‬‬\n                        ‫الترويج